function readRouteCoordinate(value, field) {
  const point = value && typeof value === "object" ? value : null;
  const lat = Number(point?.lat);
  const lng = Number(point?.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng) ||
      lat < -90 || lat > 90 || lng < -180 || lng > 180) {
    throw new HttpsError("invalid-argument", `${field} must contain valid coordinates.`);
  }
  return { lat, lng };
}

exports.estimatePetTaxiRoute = onCall({
  region: "europe-west3",
  timeoutSeconds: 20,
  secrets: [GOOGLE_MAPS_SERVER_KEY],
}, async (request) => {
  if (!request.auth) {
    throw new HttpsError("unauthenticated", "Authentication is required.");
  }

  const origin = readRouteCoordinate(request.data?.origin, "origin");
  const destination = readRouteCoordinate(request.data?.destination, "destination");
  const diagnosticContext = {
    function: "estimatePetTaxiRoute",
    region: "europe-west3",
    origin,
    destination,
    authenticated: true,
  };
  const apiKey = GOOGLE_MAPS_SERVER_KEY.value();
  if (!apiKey) {
    logger.error("Pet Taxi route estimation is not configured.", {
      ...diagnosticContext,
      failure: "secret_missing_or_unavailable",
      secret: "GOOGLE_MAPS_SERVER_KEY",
    });
    throw new HttpsError("failed-precondition", "Route estimation is not configured.");
  }

  const query = new URLSearchParams({
    origin: `${origin.lat},${origin.lng}`,
    destination: `${destination.lat},${destination.lng}`,
    mode: "driving",
    region: "tr",
    language: "tr",
    units: "metric",
    alternatives: "false",
    key: apiKey,
  });

  let response;
  try {
    response = await fetch(`https://maps.googleapis.com/maps/api/directions/json?${query}`);
  } catch (error) {
    logger.error("Pet Taxi Directions request failed", {
      ...diagnosticContext,
      failure: "network_or_fetch_exception",
      errorName: error?.name || null,
      errorMessage: error?.message || String(error),
    });
    throw new HttpsError("unavailable", "Route estimation is temporarily unavailable.");
  }

  let body;
  try {
    body = await response.json();
  } catch (error) {
    logger.error("Pet Taxi Directions returned invalid JSON", {
      ...diagnosticContext,
      failure: "invalid_google_response",
      httpStatus: response.status,
      errorName: error?.name || null,
      errorMessage: error?.message || String(error),
    });
    throw new HttpsError("internal", "Route estimation failed.");
  }
  if (!response.ok) {
    logger.error("Pet Taxi Directions returned HTTP error", {
      ...diagnosticContext,
      failure: "google_http_error",
      httpStatus: response.status,
      googleStatus: body?.status || null,
      googleErrorMessage: body?.error_message || null,
    });
    throw new HttpsError("internal", "Route estimation failed.");
  }
  if (body.status === "ZERO_RESULTS") {
    logger.info("Pet Taxi Directions returned no route", {
      ...diagnosticContext,
      failure: "google_zero_results",
      googleStatus: body.status,
    });
    throw new HttpsError("not-found", "No driving route was found.");
  }
  if (body.status !== "OK" || !Array.isArray(body.routes) || !body.routes[0]) {
    logger.error("Pet Taxi Directions API error", {
      ...diagnosticContext,
      failure: "google_api_rejection_or_invalid_route",
      httpStatus: response.status,
      googleStatus: body.status || null,
      googleErrorMessage: body.error_message || null,
      routeCount: Array.isArray(body.routes) ? body.routes.length : null,
    });
    throw new HttpsError("internal", "Route estimation failed.");
  }

  const route = body.routes[0];
  const legs = Array.isArray(route.legs) ? route.legs : [];
  const distanceMeters = legs.reduce(
    (total, leg) => total + Number(leg?.distance?.value || 0), 0);
  const durationSeconds = legs.reduce(
    (total, leg) => total + Number(leg?.duration?.value || 0), 0);
  if (!Number.isFinite(distanceMeters) || !Number.isFinite(durationSeconds) ||
      distanceMeters <= 0 || durationSeconds <= 0) {
    logger.error("Pet Taxi Directions returned incomplete route data", {
      ...diagnosticContext,
      failure: "google_incomplete_route",
      googleStatus: body.status,
      legCount: legs.length,
      distanceMeters,
      durationSeconds,
    });
    throw new HttpsError("internal", "Route estimation returned incomplete data.");
  }

  return {
    distanceKm: Number((distanceMeters / 1000).toFixed(2)),
    durationMinutes: Math.ceil(durationSeconds / 60),
    source: "google_directions_driving",
    encodedPolyline: route.overview_polyline?.points || null,
  };
});

async function settleCommittedMarketplaceSellerOrders({ db, sellerOrdersSnap, actor }) {
  const outcomes = [];
  for (const sellerDoc of sellerOrdersSnap.docs || []) {
    try {
      const result = await settlePayable({
        db,
        sector: "petshop",
        recordRef: sellerDoc.ref,
        actor,
        operationId: `marketplace-settlement-${sellerDoc.id}`,
      });
      outcomes.push({ sellerOrderId: sellerDoc.id, status: result.status });
    } catch (settlementError) {
      logger.error("settlement_retryable_failure", {
        sellerOrderId: sellerDoc.id,
        message: settlementError?.message || String(settlementError),
      });
      outcomes.push({ sellerOrderId: sellerDoc.id, status: "failed" });
    }
  }
  return {
    completed: outcomes.length === (sellerOrdersSnap.docs || []).length &&
      outcomes.every((outcome) => outcome.status === "completed"),
    outcomes,
  };
}

// M5 remains dormant until the scheduler flag and an explicit scheduler
// canary gate are enabled. The worker is bounded and each reservation is
// recovered independently so one malformed record cannot stop the batch.
exports.recoverMarketplaceInventoryM5 = onSchedule(
  {
    schedule: "every 5 minutes",
    region: "europe-west3",
    timeZone: "Europe/Istanbul",
    retryCount: 3,
  },
  async () => {
    const firestore = admin.firestore();
    const [expiry, leases] = await Promise.all([
      processExpiredInventoryReservations({ db: firestore, logger }),
      processStaleInventoryLeases({ db: firestore, logger }),
    ]);
    logger.info("marketplace_inventory_m5_recovery_batch", { expiry, leases });
    return { expiry, leases };
  }
);

async function markMarketplaceSettlementPending({ db, orderId, sellerOrderIds, outcomes }) {
  const batch = db.batch();
  const recovery = {
    settlementStatus: "settlement_pending",
    financeEligibility: "blocked",
    financeRecoveryRequired: true,
    financeRecovery: {
      reason: "settlement_pending",
      outcomes,
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    },
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
  };
  batch.set(db.collection("orders").doc(orderId), recovery, { merge: true });
  for (const sellerOrderId of sellerOrderIds || []) {
    batch.set(db.collection("sellerOrders").doc(sellerOrderId), recovery, { merge: true });
  }
  await batch.commit();
}

async function markMarketplaceSettlementCompleted({ db, orderId, sellerOrderIds }) {
  const batch = db.batch();
  const completed = {
    settlementStatus: "completed",
    financeEligibility: "eligible",
    financeRecoveryRequired: false,
    financeRecovery: null,
    updatedAt: admin.firestore.FieldValue.serverTimestamp(),
  };
  batch.set(db.collection("orders").doc(orderId), completed, { merge: true });
  for (const sellerOrderId of sellerOrderIds || []) {
    batch.set(db.collection("sellerOrders").doc(sellerOrderId), completed, { merge: true });
  }
  await batch.commit();
}

