exports.petTaxiDocumentExpiryReminderScheduler = onSchedule(
  {
    region: "europe-west3",
    schedule: "every 24 hours",
    timeZone: "Europe/Istanbul",
  },
  async () => processPetTaxiExpiryReminders({
    db,
    sendPush: async ({ token, userId, title, body, data }) => {
      try {
        await admin.messaging().send({
          token,
          notification: { title, body },
          data: Object.fromEntries(
            Object.entries(data || {}).map(([key, value]) => [key, String(value)])
          ),
          android: {
            priority: "high",
            notification: {
              sound: "default",
              channelId: "high_importance_channel",
            },
          },
          apns: {
            headers: { "apns-priority": "10" },
            payload: {
              aps: {
                alert: { title, body },
                sound: "default",
                badge: 1,
              },
            },
          },
        });
      } catch (error) {
        logger.warn("pet_taxi_expiry_reminder_push_failed", {
          userId,
          code: error?.code || null,
        });
      }
    },
  })
);

exports.migrateAdoptionCentersToBusinesses = onRequest(
  {
    region: "europe-west3",
    invoker: "private",
  },
  async (req, res) => {
    const dryRun = req.query.dryRun !== "false"; // default = true

    try {
      const snapshot = await admin
        .firestore()
        .collection("adoption_centers")
        .get();

      console.log(`🔍 Found ${snapshot.size} adoption_centers`);

      let migratedCount = 0;

      for (const doc of snapshot.docs) {
        const oldData = doc.data();
        const newBusinessData = mapAdoptionCenterToBusiness(oldData);
        const repairedOwnerUid = await findAdoptionOwnerUidForBusiness({
          db: admin.firestore(),
          businessId: doc.id,
          businessData: {
            ...newBusinessData,
            ...oldData,
            ownerUid:
              newBusinessData.ownerUid === doc.id
                ? null
                : newBusinessData.ownerUid,
          },
        });

        if (repairedOwnerUid) {
          newBusinessData.ownerUid = repairedOwnerUid;
        } else if (newBusinessData.ownerUid === doc.id) {
          newBusinessData.ownerUid = null;
        }

        // ✅ اینجا باید اضافه شود
        newBusinessData.updatedAt = admin.firestore.FieldValue.serverTimestamp();

        if (!dryRun) {
          // Marketplace P1-A Step 21e migration-writer correction: a full
          // non-merge set() would delete any existing destination
          // marketplaceSellerActivation (or any other destination-only
          // field) even though the source-exclusion above already keeps
          // it out of `newBusinessData` — merge semantics are what
          // actually make this migration's write structurally incapable
          // of touching a pre-existing destination value, without ever
          // reading that value back to preserve it (which would itself
          // make this migration a writer of the protected field).
          await admin
            .firestore()
            .collection("businesses")
            .doc(doc.id)
            .set(newBusinessData, { merge: true });
          migratedCount++;
        }
      }

      res.status(200).send({
        dryRun,
        totalFound: snapshot.size,
        migratedCount,
      });
    } catch (error) {
      console.error("❌ Migration error:", error);
      res.status(500).send(error.toString());
    }
  }
);

exports.repairAdoptionBusinessOwnerUid = onSchedule(
  {
    schedule: "every 15 minutes",
    region: "europe-west3",
  },
  async () => {
    const db = admin.firestore();
    const snap = await db
      .collection("businesses")
      .where("status", "==", "approved")
      .limit(500)
      .get();

    let checked = 0;
    let repaired = 0;

    for (const doc of snap.docs) {
      const data = doc.data() || {};
      if (!isAdoptionBusinessData(data)) continue;
      checked++;
      if (data.ownerUid !== doc.id) continue;

      const ownerUid = await repairAdoptionBusinessOwnerUidForRef({
        db,
        businessRef: doc.ref,
        businessData: data,
      });
      if (ownerUid) repaired++;
    }

    logger.info("ADOPTION OWNERUID REPAIR COMPLETE", {
      checked,
      repaired,
    });

    return null;
  }
);

function extractBusinessDocumentIdentifiers(fullText) {
  const normalizedDigitGroups = (text, minimumLength) =>
    (text.match(new RegExp(`\\d(?:[ \\t./-]*\\d){${minimumLength - 1},}`, "g")) || [])
      .map((value) => value.replace(/\D/g, ""));
  const taxGroups = normalizedDigitGroups(fullText, 10);
  const extractedTaxNumber =
    taxGroups.find((value) => value.length === 10) || null;

  const mersisLabel = /MERS[İI]S(?:\s*(?:NO|NUMARASI))?\s*[:.-]?/i.exec(
    fullText
  );
  const labeledText = mersisLabel
    ? fullText.slice(
      mersisLabel.index + mersisLabel[0].length,
      mersisLabel.index + mersisLabel[0].length + 160
    )
    : "";
  const labeledGroups = normalizedDigitGroups(labeledText, 16);
  const allGroups = normalizedDigitGroups(fullText, 16);
  const extractedMersisNumber =
    labeledGroups.find((value) => value.length === 16) ||
    allGroups.find((value) => value.length === 16) ||
    null;

  return { extractedTaxNumber, extractedMersisNumber };
}

function businessDocumentKind(fileName, metadataKind) {
  const inferredKind = [
    "tax",
    "registry",
    "signature",
    "gewerbe",
    "license",
    "ein",
  ].find((kind) => fileName.includes(`_${kind}`));
  return metadataKind || inferredKind || "unknown";
}

exports.ocrBusinessDoc = onObjectFinalized(
  {
    region: "europe-west3",
    bucket: "barkymatches-new.firebasestorage.app",
  },
  async (event) => {

    const filePath = event.data.name;
    if (!filePath || !filePath.startsWith("business_docs/")) return;

    const bucketName = event.data.bucket;
    const fileUri = `gs://${bucketName}/${filePath}`;

    // 🔥 FIX 1 — extract uid safely
    const parts = filePath.split("/");
    if (parts.length < 2) {
      console.log("Invalid file path structure");
      return;
    }

    const uid = parts[1]; // ✅ now defined safely
    const fileName = parts[parts.length - 1] || "";
    const metadataKind = event.data.metadata?.documentKind;
    const documentKind = businessDocumentKind(fileName, metadataKind);

    console.log("DOCUMENT UPLOADED", {
      uid,
      filePath,
      documentKind,
    });

    let result;

    try {
      [result] = await client.textDetection(fileUri);
    } catch (err) {
      console.error("Vision OCR failed:", err);
      return;
    }

    const detections = result.textAnnotations;
    if (!detections || detections.length === 0) return;

    const fullText = detections[0].description;

    const { extractedTaxNumber, extractedMersisNumber } =
      extractBusinessDocumentIdentifiers(fullText);

    console.log("OCR COMPLETED", {
      uid,
      documentKind,
      extractedTaxNumber,
      extractedMersisNumber,
    });

    const draftRef = admin.firestore().collection("businessDrafts").doc(uid);
    const verificationState = await admin.firestore().runTransaction(
      async (transaction) => {
        const draftSnap = await transaction.get(draftRef);
        const currentVerification = draftSnap.data()?.verification || {};
        const currentDocuments = currentVerification.documents || {};
        // companyType is client-set on businessDrafts/{uid} at selection
        // time (see business_register_page.dart) and controls whether a
        // MERSIS number is required for "verified" — see
        // functions/business/businessDocumentRequirements.js. A sole
        // proprietorship has no trade registry document to extract a
        // MERSIS number from, so requiring one here would permanently
        // block their verification.
        const companyType = draftSnap.data()?.companyType ?? null;
        const requirements = requiredTurkeyDocuments(companyType);
        const documents = {
          ...currentDocuments,
          [documentKind]: {
            status: "ocr_extracted",
            storagePath: filePath,
            extractedTaxNumber,
            extractedMersisNumber,
            rawText: fullText,
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          },
        };
        const documentResults = Object.values(documents);
        const aggregateTaxNumber = documentResults
          .map((document) => document?.extractedTaxNumber)
          .find((value) => /^\d{10}$/.test(String(value || ""))) || null;
        const aggregateMersisNumber = documentResults
          .map((document) => document?.extractedMersisNumber)
          .find((value) => /^\d{16}$/.test(String(value || ""))) || null;
        const documentsVerified =
          aggregateTaxNumber !== null &&
          (!requirements.requiresMersisNumber || aggregateMersisNumber !== null);
        const status = documentsVerified ? "verified" : "ocr_extracted";

        transaction.set(
          draftRef,
          {
            verification: {
              ...currentVerification,
              status,
              documentsVerified,
              pendingVerification: !documentsVerified,
              documents,
              ocr: {
                extractedTaxNumber: aggregateTaxNumber,
                extractedMersisNumber: aggregateMersisNumber,
                updatedAt: admin.firestore.FieldValue.serverTimestamp(),
              },
              verifiedAt: documentsVerified
                ? admin.firestore.FieldValue.serverTimestamp()
                : null,
            },
          },
          { merge: true }
        );

        return {
          status,
          documentsVerified,
          extractedTaxNumber: aggregateTaxNumber,
          extractedMersisNumber: aggregateMersisNumber,
        };
      }
    );

    console.log("FIRESTORE VERIFICATION UPDATED", {
      uid,
      documentKind,
      ...verificationState,
    });
  }
);

exports.syncBusinessDocumentVerification = onCall(
  { region: "europe-west3" },
  async (request) => {
    const uid = request.auth?.uid;
    if (!uid) {
      throw new HttpsError("unauthenticated", "Authentication required");
    }

    const draftRef = admin.firestore().collection("businessDrafts").doc(uid);
    const initialDraft = await draftRef.get();
    if (!initialDraft.exists) {
      throw new HttpsError("not-found", "Business draft not found");
    }

    const initialVerification = initialDraft.data()?.verification || {};
    const initialOcr = initialVerification.ocr || {};
    let extractedTaxNumber = String(
      initialOcr.extractedTaxNumber || ""
    ).trim();
    let extractedMersisNumber = String(
      initialOcr.extractedMersisNumber || ""
    ).trim();
    const recoveredDocuments = {};

    if (
      !/^\d{10}$/.test(extractedTaxNumber) ||
      !/^\d{16}$/.test(extractedMersisNumber)
    ) {
      const bucket = admin.storage().bucket(
        "barkymatches-new.firebasestorage.app"
      );
      const [files] = await bucket.getFiles({
        prefix: `business_docs/${uid}/`,
      });
      const latestByKind = new Map();
      for (const file of files) {
        const fileName = file.name.split("/").pop() || "";
        const kind = businessDocumentKind(
          fileName,
          file.metadata?.metadata?.documentKind
        );
        if (kind === "unknown") continue;
        const current = latestByKind.get(kind);
        if (!current || file.name > current.name) {
          latestByKind.set(kind, file);
        }
      }

      console.log("VERIFICATION OCR RECOVERY STARTED", {
        uid,
        documentKinds: [...latestByKind.keys()],
      });

      for (const [kind, file] of latestByKind.entries()) {
        try {
          const [visionResult] = await client.textDetection(
            `gs://${bucket.name}/${file.name}`
          );
          const text = visionResult.textAnnotations?.[0]?.description || "";
          const identifiers = extractBusinessDocumentIdentifiers(text);
          recoveredDocuments[kind] = {
            status: text ? "ocr_extracted" : "ocr_empty",
            storagePath: file.name,
            ...identifiers,
            rawText: text,
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
          };
          if (
            !/^\d{10}$/.test(extractedTaxNumber) &&
            identifiers.extractedTaxNumber
          ) {
            extractedTaxNumber = identifiers.extractedTaxNumber;
          }
          if (
            !/^\d{16}$/.test(extractedMersisNumber) &&
            identifiers.extractedMersisNumber
          ) {
            extractedMersisNumber = identifiers.extractedMersisNumber;
          }
        } catch (error) {
          console.error("VERIFICATION OCR RECOVERY FAILED", {
            uid,
            kind,
            storagePath: file.name,
            error: error?.message || String(error),
          });
        }
      }
    }

    const result = await admin.firestore().runTransaction(
      async (transaction) => {
        const draftSnap = await transaction.get(draftRef);
        if (!draftSnap.exists) {
          throw new HttpsError("not-found", "Business draft not found");
        }

        const verification = draftSnap.data()?.verification || {};
        const companyType = draftSnap.data()?.companyType ?? null;
        const requirements = requiredTurkeyDocuments(companyType);
        const documentsVerified =
          /^\d{10}$/.test(extractedTaxNumber) &&
          (!requirements.requiresMersisNumber ||
            /^\d{16}$/.test(extractedMersisNumber));
        const status = documentsVerified
          ? "verified"
          : verification.status || "pending_verification";

        transaction.set(
          draftRef,
          {
            verification: {
              status,
              documentsVerified,
              pendingVerification: !documentsVerified,
              documents: {
                ...(verification.documents || {}),
                ...recoveredDocuments,
              },
              ocr: {
                extractedTaxNumber: extractedTaxNumber || null,
                extractedMersisNumber: extractedMersisNumber || null,
                updatedAt: admin.firestore.FieldValue.serverTimestamp(),
              },
              verifiedAt: documentsVerified
                ? admin.firestore.FieldValue.serverTimestamp()
                : null,
            },
          },
          { merge: true }
        );

        return {
          status,
          documentsVerified,
          extractedTaxNumber,
          extractedMersisNumber,
        };
      }
    );

    console.log("VERIFICATION SYNCHRONIZED", { uid, ...result });
    return result;
  }
);

