// =====================================================
// CREATE REPORT
// =====================================================

exports.createReport = onCall(
  { region: "europe-west3" },
  async (request) => {
    if (!request.auth) {
      throw new HttpsError("unauthenticated", "Login required");
    }

    const db = admin.firestore();
    const reporterId = request.auth.uid;
    const { targetType, targetId, targetOwnerId, reasonCode, description } =
      request.data || {};

    if (!targetType || !targetId || !reasonCode) {
      throw new HttpsError("invalid-argument", "Missing parameters");
    }

    const targetConfig = TARGET_REGISTRY[targetType];
    if (!targetConfig) {
      throw new HttpsError(
        "invalid-argument",
        `Unknown report target type: ${targetType}`
      );
    }

    const targetSnap = await db
      .collection(targetConfig.collection)
      .doc(targetId)
      .get();

    if (!targetSnap.exists) {
      console.error("REPORT TARGET NOT FOUND", {
        targetType,
        targetId,
        reporterId,
      });
      throw new HttpsError(
        "not-found",
        "The item you're reporting no longer exists"
      );
    }

    const now = new Date();
    const oneHourAgo = new Date(now.getTime() - 60 * 60 * 1000);
    const twentyFourHoursAgo = new Date(now.getTime() - 24 * 60 * 60 * 1000);

    // -------------------------------------------------
    // DUPLICATE / COOLDOWN PROTECTION
    // Blocks a re-report if the reporter already has a pending report on
    // this target (any age), or any report on it at all within 24h.
    // -------------------------------------------------
    const recentOnTarget = await db
      .collection("reports")
      .where("reporterId", "==", reporterId)
      .where("targetType", "==", targetType)
      .where("targetId", "==", targetId)
      .orderBy("createdAt", "desc")
      .limit(5)
      .get();

    const hasPending = recentOnTarget.docs.some(
      (doc) => doc.data().status === "pending"
    );
    const hasRecent = recentOnTarget.docs.some((doc) => {
      const createdAt = doc.data().createdAt;
      return createdAt && createdAt.toDate() > twentyFourHoursAgo;
    });

    if (hasPending || hasRecent) {
      throw new HttpsError("already-exists", "You already reported this item");
    }

    // -------------------------------------------------
    // RATE LIMIT
    // -------------------------------------------------
    const recentReports = await db
      .collection("reports")
      .where("reporterId", "==", reporterId)
      .where("createdAt", ">", oneHourAgo)
      .get();

    if (recentReports.size >= 10) {
      throw new HttpsError("resource-exhausted", "Too many reports");
    }

    // -------------------------------------------------
    // CREATE REPORT
    // -------------------------------------------------
    const reportRef = db.collection("reports").doc();

    await reportRef.set({
      targetType,
      targetId,
      targetOwnerId: targetOwnerId || null,
      reporterId,
      reasonCode,
      description: description || null,
      status: "pending",
      source: "user",
      reviewedAt: null,
      reviewedBy: null,
      moderationAction: null,
      moderationNotes: null,
      createdAt: admin.firestore.FieldValue.serverTimestamp(),
      updatedAt: admin.firestore.FieldValue.serverTimestamp(),
    });

    const statsRef = db.collection("admin_stats").doc("moderation");
    await statsRef.set(
      {
        reportsToday: admin.firestore.FieldValue.increment(1),
        reportsTotal: admin.firestore.FieldValue.increment(1),
        lastReportAt: admin.firestore.FieldValue.serverTimestamp(),
      },
      { merge: true }
    );

    console.log("REPORT CREATED", {
      reportId: reportRef.id,
      targetType,
      targetId,
      reporterId,
    });

    return { success: true, reportId: reportRef.id };
  }
);

// =====================================================
// REVIEW REPORT (ADMIN)
// =====================================================

exports.reviewReport = onCall(
  { region: "europe-west3" },
  async (request) => {
    const db = admin.firestore();

    try {
      const adminUid = await requireAdmin(db, request);
      const { reportId, action, moderationAction, notes } = request.data || {};

      if (!reportId || !action) {
        throw new HttpsError("invalid-argument", "Missing parameters");
      }
      if (action !== "approved" && action !== "rejected") {
        throw new HttpsError("invalid-argument", "Invalid action");
      }

      const reportRef = db.collection("reports").doc(reportId);
      const reportSnap = await reportRef.get();

      if (!reportSnap.exists) {
        console.error("REPORT NOT FOUND", { reportId });
        throw new HttpsError("not-found", "Report not found");
      }

      const reportData = reportSnap.data() || {};
      // Backward compatibility: reports created before this schema used
      // `type`/`reportedBy` instead of `targetType`/`reporterId`.
      const targetType = reportData.targetType ?? reportData.type;
      const targetId = reportData.targetId;

      if (reportData.status && reportData.status !== "pending") {
        throw new HttpsError(
          "failed-precondition",
          "This report has already been reviewed"
        );
      }
      if (!targetType || !targetId) {
        throw new HttpsError(
          "failed-precondition",
          "Report is missing target data"
        );
      }

      let appliedAction = null;

      if (action === "approved") {
        if (!moderationAction) {
          throw new HttpsError(
            "invalid-argument",
            "moderationAction is required to approve a report"
          );
        }

        const targetConfig = TARGET_REGISTRY[targetType];
        if (!targetConfig || !targetConfig.actions[moderationAction]) {
          throw new HttpsError(
            "invalid-argument",
            `Unknown moderation action "${moderationAction}" for target type "${targetType}"`
          );
        }

        const targetSnap = await db
          .collection(targetConfig.collection)
          .doc(targetId)
          .get();

        if (!targetSnap.exists) {
          console.error("REPORT TARGET NOT FOUND", {
            reportId,
            targetType,
            targetId,
          });
          appliedAction = "target_not_found";
        } else {
          await targetConfig.actions[moderationAction](db, targetId, {
            adminUid,
            notes: notes || "",
            reportId,
            createNotification,
          });
          appliedAction = moderationAction;
        }
      }

      await reportRef.update({
        status: action,
        reviewedAt: admin.firestore.FieldValue.serverTimestamp(),
        reviewedBy: adminUid,
        moderationAction: appliedAction,
        moderationNotes: notes || null,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });

      await db.collection("admin_logs").add({
        action: action === "approved" ? "REPORT_APPROVED" : "REPORT_REJECTED",
        entityType: targetType,
        entityId: targetId,
        reportId,
        performedBy: adminUid,
        moderationAction: appliedAction,
        reason: notes || "",
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
      });

      console.log(
        action === "approved" ? "REPORT APPROVED" : "REPORT REJECTED",
        { reportId, targetType, targetId, adminUid, moderationAction: appliedAction }
      );

      return { success: true, targetFound: appliedAction !== "target_not_found" };
    } catch (err) {
      if (err instanceof HttpsError) throw err;
      console.error("REPORT UPDATE FAILED", err);
      throw new HttpsError("internal", "REPORT_UPDATE_FAILED", toPlainError(err));
    }
  }
);

// =====================================================
// RESTORE MODERATION TARGET (ADMIN) — the generic "undo" control shown
// whenever a target is currently in a non-active moderation state,
// independent of any specific report.
// =====================================================

exports.restoreModerationTarget = onCall(
  { region: "europe-west3" },
  async (request) => {
    const db = admin.firestore();

    try {
      const adminUid = await requireAdmin(db, request);
      const { targetType, targetId, notes } = request.data || {};

      if (!targetType || !targetId) {
        throw new HttpsError("invalid-argument", "Missing parameters");
      }

      const targetConfig = TARGET_REGISTRY[targetType];
      if (!targetConfig || !targetConfig.actions.restore) {
        throw new HttpsError(
          "invalid-argument",
          `Target type "${targetType}" does not support restore`
        );
      }

      const targetSnap = await db
        .collection(targetConfig.collection)
        .doc(targetId)
        .get();

      if (!targetSnap.exists) {
        console.error("REPORT TARGET NOT FOUND", { targetType, targetId });
        throw new HttpsError("not-found", "Target no longer exists");
      }

      await targetConfig.actions.restore(db, targetId, {
        adminUid,
        notes: notes || "",
        reportId: null,
        createNotification,
      });

      await db.collection("admin_logs").add({
        action: "TARGET_RESTORED",
        entityType: targetType,
        entityId: targetId,
        performedBy: adminUid,
        reason: notes || "",
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
      });

      console.log("TARGET RESTORED", { targetType, targetId, adminUid });

      return { success: true };
    } catch (err) {
      if (err instanceof HttpsError) throw err;
      console.error("REPORT UPDATE FAILED", err);
      throw new HttpsError("internal", "RESTORE_FAILED", toPlainError(err));
    }
  }
);

// Convenience alias for the user-restore path specifically (same underlying
// registry action + audit trail as restoreModerationTarget).
exports.reactivateUser = onCall(
  { region: "europe-west3" },
  async (request) => {
    const db = admin.firestore();

    try {
      const adminUid = await requireAdmin(db, request);
      const { userId, notes } = request.data || {};

      if (!userId) {
        throw new HttpsError("invalid-argument", "userId required");
      }

      const targetSnap = await db.collection("users").doc(userId).get();
      if (!targetSnap.exists) {
        console.error("REPORT TARGET NOT FOUND", {
          targetType: "user",
          targetId: userId,
        });
        throw new HttpsError("not-found", "User not found");
      }

      await TARGET_REGISTRY.user.actions.restore(db, userId, {
        adminUid,
        notes: notes || "",
        reportId: null,
        createNotification,
      });

      await db.collection("admin_logs").add({
        action: "TARGET_RESTORED",
        entityType: "user",
        entityId: userId,
        performedBy: adminUid,
        reason: notes || "",
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
      });

      console.log("TARGET RESTORED", {
        targetType: "user",
        targetId: userId,
        adminUid,
      });

      return { success: true };
    } catch (err) {
      if (err instanceof HttpsError) throw err;
      console.error("REPORT UPDATE FAILED", err);
      throw new HttpsError("internal", "REACTIVATE_FAILED", toPlainError(err));
    }
  }
);

exports.createComplaint = onCall(
  {
    region: "europe-west3",
  },
  async (request) => {
    const db = admin.firestore();
    const uid = request.auth?.uid;

    if (!uid) {
      throw new HttpsError(
        "unauthenticated",
        "User must be logged in."
      );
    }

    const {
      targetType,
      targetId,
      category,
      title,
      description,
      severity,
      priority,
      reporterSnapshot,
      targetSnapshot,
      attachments
    } = request.data || {};

    if (!targetType || !targetId) {
      throw new HttpsError(
        "invalid-argument",
        "targetType and targetId required."
      );
    }

    if (!category) {
      throw new HttpsError(
        "invalid-argument",
        "category required."
      );
    }

    if (!description || description.length < 5) {
      throw new HttpsError(
        "invalid-argument",
        "description too short."
      );
    }

    // جلوگیری از complaint تکراری
    const duplicateSnapshot = await db
      .collection("complaints")
      .where("createdBy", "==", uid)
      .where("targetId", "==", targetId)
      .where(
        "status",
        "in",
        ["open", "under_review", "waiting_user", "escalated"]
      )
      .limit(1)
      .get();

    if (!duplicateSnapshot.empty) {
      throw new HttpsError(
        "already-exists",
        "You already have an open complaint for this item."
      );
    }

    const complaintRef = db.collection("complaints").doc();

    const now = admin.firestore.FieldValue.serverTimestamp();

    // ایجاد complaint
    await complaintRef.set({
      complaintId: complaintRef.id,
      createdBy: uid,
      createdAt: now,
      updatedAt: now,

      targetType,
      targetId,

      category,
      severity: severity || "medium",
      priority: priority || "normal",

      title: title || "",
      description,

      status: "open",

      assignedAdminId: null,
      assignedAt: null,

      reporterSnapshot: reporterSnapshot || null,
      targetSnapshot: targetSnapshot || null,

      evidenceCount: attachments ? attachments.length : 0,

      messageCount: 1,
      lastMessageAt: now,

      lastAdminActionAt: null,

      resolutionType: null,
      resolutionSummary: null,

      linkedReportIds: [],
      linkedEntityIds: [],

      fraudFlags: [],

      isArchived: false
    });

    // پیام اولیه complaint
    await complaintRef.collection("messages").add({
      senderType: "user",
      senderId: uid,
      text: description,
      attachments: attachments || [],
      createdAt: now,
      isInternalNote: false
    });

    // آمار admin
    await db
      .collection("admin_stats")
      .doc("complaints")
      .set(
        {
          totalOpen: admin.firestore.FieldValue.increment(1),
          complaintsToday: admin.firestore.FieldValue.increment(1),
          lastComplaintAt: now
        },
        { merge: true }
      );

    return {
      success: true,
      complaintId: complaintRef.id
    };
  }
);

exports.reviewComplaint = onCall(async (request) => {
  const db = admin.firestore();
  const adminUid = request.auth?.uid;

  if (!adminUid) {
    throw new HttpsError("unauthenticated", "Admin must be logged in.");
  }

  const {
    complaintId,
    action,
    note,
  } = request.data || {};

  if (!complaintId || !action) {
    throw new HttpsError(
      "invalid-argument",
      "complaintId and action required"
    );
  }

  const complaintRef = db
    .collection("complaints")
    .doc(complaintId);

  const complaintDoc = await complaintRef.get();

  if (!complaintDoc.exists) {
    throw new HttpsError("not-found", "Complaint not found");
  }

  const complaint = complaintDoc.data();

  const now = admin.firestore.FieldValue.serverTimestamp();

  let newStatus = complaint.status;

  if (action === "resolve") {
    newStatus = "resolved";
  }

  if (action === "dismiss") {
    newStatus = "dismissed";
  }

  if (action === "escalate") {
    newStatus = "escalated";
  }

  if (action === "review") {
    newStatus = "under_review";
  }

  await complaintRef.update({
    status: newStatus,
    updatedAt: now,
    lastAdminActionAt: now,
    assignedAdminId: adminUid
  });

  // action log

  await complaintRef
    .collection("actions")
    .add({
      action: action,
      adminId: adminUid,
      note: note || "",
      createdAt: now
    });

  // update stats

  if (action === "resolve") {

    await db
      .collection("admin_stats")
      .doc("complaints")
      .set({
        totalOpen: admin.firestore.FieldValue.increment(-1),
        totalResolved: admin.firestore.FieldValue.increment(1)
      }, { merge: true });

  }

  if (action === "dismiss") {

    await db
      .collection("admin_stats")
      .doc("complaints")
      .set({
        totalOpen: admin.firestore.FieldValue.increment(-1),
        totalDismissed: admin.firestore.FieldValue.increment(1)
      }, { merge: true });

  }

  return {
    success: true,
    newStatus: newStatus
  };

});
exports.updateAdminDashboardStats = onSchedule(
  {
    region: "europe-west3",
    schedule: "every 5 minutes"
  },
  async () => {

    const db = admin.firestore();

    const businesses = await db.collection("businesses").get();

    let approved = 0;
    let rejected = 0;
    let suspended = 0;
    let risk = 0;

    businesses.forEach(doc => {

      const data = doc.data();

      if (data.status === "approved") approved++;
      if (data.status === "rejected") rejected++;
      if (data.status === "suspended") suspended++;

      const flags = data.trust?.riskFlags;

      if (flags && flags.length > 0) risk++;

    });

    await db.collection("admin_stats")
      .doc("dashboard")
      .set({

        businessesTotal: businesses.size,
        businessesApproved: approved,
        businessesRejected: rejected,
        businessesSuspended: suspended,
        riskFlags: risk,
        updatedAt: admin.firestore.FieldValue.serverTimestamp()

      });

  }
);


