// Settlement-only retry. This endpoint never contacts a payment provider and
// never replays or mutates the verified payment result.
exports.retrySettlement = onCall(
  {
    region: "europe-west3",
    timeoutSeconds: 30,
    memory: "256MiB",
  },
  async (request) => {
    const auth = request.auth;
    if (!auth) {
      throw new HttpsError("unauthenticated", "Login required.");
    }

    const userSnap = await db.collection("users").doc(auth.uid).get();
    if (userSnap.data()?.role !== "admin") {
      throw new HttpsError("permission-denied", "Admin only.");
    }

    const sector = String(request.data?.sector || "").trim().toLowerCase();
    const payableId = String(request.data?.payableId || "").trim();
    if (!sector || !payableId) {
      throw new HttpsError(
        "invalid-argument",
        "sector and payableId are required."
      );
    }

    const adapter = payoutEngine.getPayoutSectorAdapter(sector);
    const result = await settlePayable({
      db,
      sector,
      recordRef: db.collection(adapter.collection).doc(payableId),
      actor: { type: "user", id: auth.uid },
    });

    return { success: true, sector, payableId, settlement: result.status };
  }
);

exports.verifyPaymentByOrderId = onCall(
  {
    region: "europe-west3",
    timeoutSeconds: 60,
    memory: "512MiB",
    secrets: [
      IYZICO_API_KEY,
      IYZICO_SECRET_KEY,
      resendApiKey,
      ORDER_EXTERNAL_NOTIFICATIONS_ENABLED,
    ],
  },
  async (request) => {
    try {
      const auth = request.auth;
      if (!auth?.uid) {
        throw new HttpsError("unauthenticated", "Login required.");
      }

      const { orderId } = request.data || {};
      const rawOrderId = request.data?.orderId;

      const safeOrderId = normalizeText(orderId);

      if (!safeOrderId) {
        throw new HttpsError("invalid-argument", "Missing orderId");
      }

      const db = admin.firestore();
      const now = admin.firestore.FieldValue.serverTimestamp();
      const orderRef = db.collection("orders").doc(safeOrderId);
      const orderSnap = await orderRef.get();

      if (!orderSnap.exists) {
        logger.error("VERIFY_ORDER_NOT_FOUND", {
          orderId: safeOrderId,
        });
        throw new HttpsError("not-found", "Order not found");
      }

      const orderData = orderSnap.data() || {};
      const paymentToken = orderData?.payment?.token || null;
      let paymentCallbackClaim = null;

      // idempotent
      const durableManagedRecovery = hasVerifiedProviderPayment(orderData) &&
        ["committed", "commit_pending", "settlement_pending"].includes(
          normalizeLower(orderData.inventoryStatus)
        );
      if (
        (
          normalizeLower(orderData.status) === "paid" ||
          normalizeLower(orderData?.payment?.status) === "paid" ||
          normalizeLower(orderData?.payment?.status) === "success" ||
          durableManagedRecovery
        ) &&
        (durableManagedRecovery ||
          ![FINANCIAL_STATUS.PENDING, FINANCIAL_STATUS.REQUIRES_REPAIR].includes(
            normalizeLower(orderData.financialStatus)
          ))
      ) {
        const existingSellerOrderIds = Array.isArray(orderData.sellerOrderIds)
          ? orderData.sellerOrderIds.map(String)
          : [];
        const existingSellerSnaps = await Promise.all(
          existingSellerOrderIds.map((id) => db.collection("sellerOrders").doc(id).get())
        );
        const managedMarketplaceOrder = isInventoryManagedOrder(
          orderData,
          existingSellerSnaps.map((snap) => snap.data() || {})
        );
        if (managedMarketplaceOrder) {
          const paymentId = orderData?.payment?.paymentId ||
            orderData?.payment?.paymentTransactionId || safeOrderId;
          paymentCallbackClaim = await claimPaymentCallback({
            db,
            provider: "iyzico",
            orderId: safeOrderId,
            paymentId,
            providerEventId: orderData?.payment?.conversationId || paymentId,
            amount: orderData?.payment?.paidPrice ?? orderData?.pricing?.grandTotal,
            currency: orderData?.payment?.currency || orderData?.pricing?.currency,
          });
          if (paymentCallbackClaim.status === "processing") {
            return { success: false, pending: true, orderId: safeOrderId, inventoryStatus: "commit_pending" };
          }
          if (paymentCallbackClaim.status !== "already_processed") {
            const commitResult = await commitVerifiedMarketplaceInventory({
              db,
              orderId: safeOrderId,
              provider: "iyzico",
              paymentId,
              amount: orderData?.payment?.paidPrice ?? orderData?.pricing?.grandTotal,
              currency: orderData?.payment?.currency || orderData?.pricing?.currency,
            });
            if (commitResult.status === "manual_review") {
              await recordLatePaymentAfterExpiry({
                db,
                orderId: safeOrderId,
                provider: "iyzico",
                paymentId,
                amount: orderData?.payment?.paidPrice ?? orderData?.pricing?.grandTotal,
                currency: orderData?.payment?.currency || orderData?.pricing?.currency,
              }).catch((error) => logger.warn("iyzico_late_payment_recovery_record_failed", {
                orderId: safeOrderId,
                reason: error.code || "internal_retryable",
              }));
              await markPaymentCallbackManualReview({
                ref: paymentCallbackClaim.ref,
                ownerToken: paymentCallbackClaim.ownerToken,
                result: commitResult,
                errorData: { code: commitResult.reason || "manual_review" },
              });
              return { success: false, pending: true, recoveryRequired: true, orderId: safeOrderId, inventoryStatus: "manual_review" };
            }
            if (["commit_pending", "missing"].includes(commitResult.status)) {
              await markPaymentCallbackCommitPending({
                ref: paymentCallbackClaim.ref,
                ownerToken: paymentCallbackClaim.ownerToken,
                result: commitResult,
                errorData: { code: commitResult.reason || "commit_pending" },
              });
              return { success: false, pending: true, orderId: safeOrderId, inventoryStatus: "commit_pending" };
            }
            const settlement = await settleCommittedMarketplaceSellerOrders({
              db,
              sellerOrdersSnap: existingSellerSnaps,
              actor: { type: "system", id: "iyzico_settlement" },
            });
            if (!settlement.completed) {
              await markMarketplaceSettlementPending({
                db,
                orderId: safeOrderId,
                sellerOrderIds: existingSellerOrderIds,
                outcomes: settlement.outcomes,
              });
              await markPaymentCallbackSettlementPending({
                ref: paymentCallbackClaim.ref,
                ownerToken: paymentCallbackClaim.ownerToken,
                result: { status: "settlement_pending", orderId: safeOrderId },
                errorData: { code: "settlement_pending" },
              });
              return { success: false, pending: true, orderId: safeOrderId, inventoryStatus: "settlement_pending" };
            }
            await markMarketplaceSettlementCompleted({
              db,
              orderId: safeOrderId,
              sellerOrderIds: existingSellerOrderIds,
            });
            await completePaymentCallback({
              ref: paymentCallbackClaim.ref,
              ownerToken: paymentCallbackClaim.ownerToken,
              result: commitResult,
            });
          }
        }
        const cartReconciliation = await reconcilePaidMarketplaceCart(
          safeOrderId
        );
        return {
          success: true,
          alreadyProcessed: true,
          orderId: safeOrderId,
          cartReconciled: cartReconciliation.reconciled === true,
          paymentId: orderData?.payment?.paymentId || null,
          sellerOrderIds: Array.isArray(orderData?.sellerOrderIds)
            ? orderData.sellerOrderIds
            : [],
          inventoryStatus: managedMarketplaceOrder ? "committed" : "not_applicable",
        };
      }

      if (!paymentToken) {
        throw new HttpsError("failed-precondition", "Missing payment token in order");
      }

      const iyzi = new Iyzipay({
        apiKey: IYZICO_API_KEY.value(),
        secretKey: IYZICO_SECRET_KEY.value(),
        uri: "https://sandbox-api.iyzipay.com",
      });

      const result = await new Promise((resolve, reject) => {
        iyzi.checkoutForm.retrieve(
          {
            locale: Iyzipay.LOCALE.TR,
            token: paymentToken,
          },
          (err, res) => {
            if (err) return reject(err);
            return resolve(res);
          }
        );
      });

      logger.info("💰 VERIFY RESULT", {
        orderId: safeOrderId,
        paymentStatus: result?.paymentStatus || null,
        status: result?.status || null,
        paymentId: result?.paymentId || null,
      });

      const sellerOrdersSnap = await db
        .collection("sellerOrders")
        .where("rootOrderId", "==", safeOrderId)
        .get();

      const sellerOrderIds = sellerOrdersSnap.docs.map((d) => d.id);

      const hardFailure =
        !result ||
        normalizeLower(result?.status) === "failure" ||
        normalizeLower(result?.paymentStatus) === "failure";

      const success =
        normalizeLower(result?.status) === "success" &&
        normalizeLower(result?.paymentStatus) === "success";

      const paymentTransactionIds = extractPaymentTransactionIds(
        result?.itemTransactions
      );
      const paymentTransactionId =
        paymentTransactionIds.length > 0
          ? paymentTransactionIds[0]
          : result?.paymentTransactionId?.toString?.() ||
          result?.paymentTransactionId ||
          null;

      console.log("💳 PAYMENT TRANSACTION ID", paymentTransactionId);
      if (!paymentTransactionId) {
        console.warn("⚠️ Missing paymentTransactionId");
      }

      // -------------------------
      // HARD FAILURE
      // -------------------------
      if (hardFailure) {
        const latestOrderSnap = await orderRef.get();
        if (latestOrderSnap.exists && hasVerifiedProviderPayment(latestOrderSnap.data() || {})) {
          const latest = latestOrderSnap.data() || {};
          return {
            success: latest.inventoryStatus === "committed" &&
              latest.settlementStatus !== "settlement_pending",
            pending: latest.inventoryStatus !== "committed" ||
              latest.settlementStatus === "settlement_pending",
            orderId: safeOrderId,
            sellerOrderIds,
            inventoryStatus: latest.settlementStatus === "settlement_pending"
              ? "settlement_pending"
              : latest.inventoryStatus || "commit_pending",
          };
        }
        const latestOrderData = latestOrderSnap.exists ? latestOrderSnap.data() || {} : orderData;
        const managedFailure = isInventoryManagedOrder(
          { ...latestOrderData, __id: safeOrderId },
          sellerOrdersSnap.docs.map((doc) => doc.data() || {})
        );
        const failureBusinessIds = sellerOrdersSnap.docs
          .map((doc) => doc.data()?.businessId || doc.data()?.shopId || null)
          .filter(Boolean);
        if (
          managedFailure &&
          m5FeatureEnabled("failure_release", {
            buyerUid: latestOrderData.buyerUid || latestOrderData.userId || auth.uid,
            businessIds: failureBusinessIds,
          })
        ) {
          const releaseResult = await releaseMarketplaceInventory({
            db,
            orderId: safeOrderId,
            reason: result?.errorCode || result?.errorMessage || "iyzico_payment_failure",
            paymentState: latestOrderData.providerPaymentStatus || latestOrderData.providerPaymentState || "pending",
          });
          if (["manual_review", "release_pending"].includes(releaseResult.status)) {
            return {
              success: false,
              pending: true,
              recoveryRequired: true,
              orderId: safeOrderId,
              sellerOrderIds,
              inventoryStatus: releaseResult.status,
            };
          }
        }
        const batch = db.batch();

        batch.set(
          orderRef,
          {
            status: "payment_failed",
            paymentStatus: "failed",
            payment: {
              ...(orderData.payment || {}),
              status: "failed",
              provider: "iyzico",
              errorMessage: result?.errorMessage || null,
              errorCode: result?.errorCode || null,
              raw: result || null,
            },
            updatedAt: now,
            timeline: admin.firestore.FieldValue.arrayUnion({
              status: "payment_failed",
              at: new Date().toISOString(),
              by: "system",
            }),
          },
          { merge: true }
        );

        for (const doc of sellerOrdersSnap.docs) {
          batch.set(
            doc.ref,
            {
              status: "failed",
              paymentStatus: "failed",
              payment: {
                ...(doc.data()?.payment || {}),
                status: "failed",
                provider: "iyzico",
                errorMessage: result?.errorMessage || null,
                errorCode: result?.errorCode || null,
              },
              updatedAt: now,
              timeline: admin.firestore.FieldValue.arrayUnion({
                status: "payment_failed",
                at: new Date().toISOString(),
                by: "system",
              }),
            },
            { merge: true }
          );
        }

        await batch.commit();

        throw new HttpsError(
          "failed-precondition",
          result?.errorMessage || "Payment failed"
        );
      }

      // -------------------------
      // STILL PENDING
      // -------------------------
      if (!success) {
        const latestOrderSnap = await orderRef.get();
        const latestOrderData = latestOrderSnap.exists ? latestOrderSnap.data() || {} : {};
        if (hasVerifiedProviderPayment(latestOrderData)) {
          return {
            success: latestOrderData.inventoryStatus === "committed",
            pending: latestOrderData.inventoryStatus !== "committed",
            orderId: safeOrderId,
            sellerOrderIds,
            inventoryStatus: latestOrderData.settlementStatus === "settlement_pending"
              ? "settlement_pending"
              : latestOrderData.inventoryStatus || "commit_pending",
          };
        }
        await orderRef.set(
          {
            status: "payment_pending",
            paymentStatus: "pending",
            payment: {
              ...(orderData.payment || {}),
              status: "pending",
              provider: "iyzico",
              raw: result || null,
            },
            updatedAt: now,
          },
          { merge: true }
        );

        return {
          success: false,
          pending: true,
          orderId: safeOrderId,
          paymentId: result?.paymentId || null,
          sellerOrderIds,
        };
      }

      const managedMarketplaceOrder = isInventoryManagedOrder(
        orderData,
        sellerOrdersSnap.docs.map((doc) => doc.data() || {})
      );
      if (managedMarketplaceOrder) {
        const callbackPaymentId = result?.paymentId || paymentTransactionId || safeOrderId;
        let verifiedEvidence;
        try {
          verifiedEvidence = validateVerifiedPaymentAmount({
            rootData: orderData,
            amount: result?.paidPrice ?? result?.price,
            currency: result?.currency,
          });
        } catch (paymentError) {
          await markInventoryManualReview({
            db,
            rootRef: orderRef,
            sellerRefs: sellerOrdersSnap.docs.map((doc) => doc.ref),
            reason: paymentError.code || "payment_evidence_conflict",
            details: paymentError.details || {},
          });
          throw new HttpsError(
            "failed-precondition",
            "Payment requires verification review"
          );
        }
        paymentCallbackClaim = await claimPaymentCallback({
          db,
          provider: "iyzico",
          orderId: safeOrderId,
          paymentId: callbackPaymentId,
          providerEventId: result?.conversationId || paymentTransactionId || callbackPaymentId,
          amount: verifiedEvidence.amount,
          currency: verifiedEvidence.currency,
        });
        if (paymentCallbackClaim.status === "already_processed") {
          return {
            success: true,
            alreadyProcessed: true,
            orderId: safeOrderId,
            paymentId: callbackPaymentId,
            sellerOrderIds,
            inventoryStatus: "committed",
          };
        }
        if (paymentCallbackClaim.status === "processing") {
          return { success: false, pending: true, orderId: safeOrderId, inventoryStatus: "commit_pending" };
        }
      }

      // -------------------------
      // SUCCESS
      // -------------------------
      const batch = db.batch();
      const marketplaceFinancialStatus = sellerOrdersSnap.docs.every((doc) =>
        hasCompleteFinancial(doc.data()?.financial)
      )
        ? FINANCIAL_STATUS.VERIFIED
        : FINANCIAL_STATUS.REQUIRES_REPAIR;

      batch.set(
        orderRef,
        {
          status: managedMarketplaceOrder
            ? "payment_verified_pending_inventory"
            : "paid",
          paymentStatus: managedMarketplaceOrder ? "pending" : "paid",
          paidAt: now,
          cartCleared: true,
          payment: {
            ...(orderData.payment || {}),
            status: managedMarketplaceOrder ? "pending" : "paid",
            provider: "iyzico",
            paymentId: result?.paymentId || null,
            paymentTransactionId,
            paymentTransactionIds,
            itemTransactions: result?.itemTransactions || [],
            conversationId: result?.conversationId || null,
            paidPrice: asNumber(result?.paidPrice, 0),
            price: asNumber(result?.price, 0),
            currency: result?.currency || orderData?.currency || "TRY",
            installment: asNumber(result?.installment, 1),
            raw: result,
          },
          financialStatus: marketplaceFinancialStatus,
          updatedAt: now,
          timeline: admin.firestore.FieldValue.arrayUnion({
            status: "paid",
            at: new Date().toISOString(),
            by: "system",
          }),
        },
        { merge: true }
      );

      const sellerBusinessIds = new Set();
      const sellerOrderIdsByBusiness = new Map();

      for (const doc of sellerOrdersSnap.docs) {
        const sellerOrder = doc.data() || {};
        const businessId = sellerOrder.businessId || sellerOrder.shopId || null;
        if (businessId) {
          sellerBusinessIds.add(String(businessId));
          if (!sellerOrderIdsByBusiness.has(String(businessId))) {
            sellerOrderIdsByBusiness.set(String(businessId), doc.id);
          }
        }

        batch.set(
          doc.ref,
          {
            status: managedMarketplaceOrder
              ? "payment_verified_pending_inventory"
              : "paid",
            paymentStatus: managedMarketplaceOrder ? "pending" : "paid",
            financialStatus: managedMarketplaceOrder
              ? FINANCIAL_STATUS.REQUIRES_REPAIR
              : hasCompleteFinancial(sellerOrder.financial)
                ? FINANCIAL_STATUS.VERIFIED
                : FINANCIAL_STATUS.REQUIRES_REPAIR,
            paidAt: now,
            payment: {
              ...(sellerOrder.payment || {}),
              status: managedMarketplaceOrder ? "pending" : "paid",
              provider: "iyzico",
              paymentProvider: sellerOrder.payment?.paymentProvider || "iyzico",
              paymentId: result?.paymentId || null,
              paymentTransactionId,
              paymentTransactionIds,
              itemTransactions: result?.itemTransactions || [],
              conversationId: result?.conversationId || null,
              paidPrice: asNumber(result?.paidPrice, 0),
              price: asNumber(result?.price, 0),
              currency: result?.currency || sellerOrder?.currency || "TRY",
              installment: asNumber(result?.installment, 1),
              paymentTransactionId,
              paymentTransactionIds,
              itemTransactions: result?.itemTransactions || [],
              iyzicoPaymentTransactionId: paymentTransactionId || null,
            },
            updatedAt: now,
            timeline: admin.firestore.FieldValue.arrayUnion({
              status: "paid",
              at: new Date().toISOString(),
              by: "system",
            }),
          },
          { merge: true }
        );
      }

      await batch.commit();
      if (paymentCallbackClaim) {
        const commitResult = await commitVerifiedMarketplaceInventory({
          db,
          orderId: safeOrderId,
          provider: "iyzico",
          paymentId: result?.paymentId || paymentTransactionId || safeOrderId,
          amount: verifiedEvidence?.amount ?? result?.paidPrice ?? result?.price,
          currency: verifiedEvidence?.currency ?? result?.currency,
        });
        if (commitResult.status === "manual_review") {
          await recordLatePaymentAfterExpiry({
            db,
            orderId: safeOrderId,
            provider: "iyzico",
            paymentId: result?.paymentId || paymentTransactionId || safeOrderId,
            amount: verifiedEvidence?.amount ?? result?.paidPrice ?? result?.price,
            currency: verifiedEvidence?.currency ?? result?.currency,
          }).catch((error) => logger.warn("iyzico_late_payment_recovery_record_failed", {
            orderId: safeOrderId,
            reason: error.code || "internal_retryable",
          }));
          await markPaymentCallbackManualReview({
            ref: paymentCallbackClaim.ref,
            ownerToken: paymentCallbackClaim.ownerToken,
            result: commitResult,
            errorData: { code: commitResult.reason || "manual_review" },
          });
          return { success: false, pending: true, recoveryRequired: true, orderId: safeOrderId, inventoryStatus: "manual_review" };
        }
        if (["commit_pending", "missing"].includes(commitResult.status)) {
          await markPaymentCallbackCommitPending({
            ref: paymentCallbackClaim.ref,
            ownerToken: paymentCallbackClaim.ownerToken,
            result: commitResult,
            errorData: { code: commitResult.reason || "commit_pending" },
          });
          return { success: false, pending: true, orderId: safeOrderId, inventoryStatus: "commit_pending" };
        }
        const settlement = await settleCommittedMarketplaceSellerOrders({
          db,
          sellerOrdersSnap,
          actor: { type: "system", id: "iyzico_settlement" },
        });
        if (!settlement.completed) {
          await markMarketplaceSettlementPending({
            db,
            orderId: safeOrderId,
            sellerOrderIds,
            outcomes: settlement.outcomes,
          });
          await markPaymentCallbackSettlementPending({
            ref: paymentCallbackClaim.ref,
            ownerToken: paymentCallbackClaim.ownerToken,
            result: { status: "settlement_pending", orderId: safeOrderId },
            errorData: { code: "settlement_pending" },
          });
          return { success: false, pending: true, orderId: safeOrderId, inventoryStatus: "settlement_pending" };
        }
        await markMarketplaceSettlementCompleted({
          db,
          orderId: safeOrderId,
          sellerOrderIds,
        });
      }
      const cartReconciliation = await reconcilePaidMarketplaceCart(
        safeOrderId
      );

      const buyerUid = orderData.buyerUid || orderData.userId || auth.uid;

      if (buyerUid) {
        await createNotification(db, {
          recipientUserId: buyerUid,
          userId: buyerUid,
          type: "order_paid",
          title: "Order confirmed 🎉",
          body: "Your order has been successfully placed.",
          orderId: safeOrderId,
        });
      }

      for (const doc of sellerOrdersSnap.docs) {
        const sellerOrderId = doc.id;
        const sellerData = doc.data() || {};
        const businessId = sellerData.businessId || sellerData.shopId || null;

        const businessSnap = await db.collection("businesses").doc(businessId).get();
        const businessData = businessSnap.exists ? businessSnap.data() || {} : {};
        const ownerUid = businessSnap.exists
          ? businessData.ownerUid || businessData.uid || null
          : null;
        const businessToken = businessData.fcmToken || null;

        console.log('🔔 PUSH TYPE = new_paid_order');
        console.log('🔔 RECIPIENT UID =', ownerUid);
        console.log('🔔 BUSINESS ID =', businessId);

        if (ownerUid) {
          const notificationKey = `new_order_${sellerOrderId}`;
          const orderNotificationDebug = {
            type: "new_order",
            orderId: String(safeOrderId || ""),
            sellerOrderId: String(sellerOrderId || ""),
            businessId: String(businessId || ""),
            recipientUserId: String(ownerUid || ""),
            notificationKey,
          };
          const existingNotificationSnap = await db
            .collection("notifications")
            .where("notificationKey", "==", notificationKey)
            .limit(1)
            .get();

          console.log("📦 ORDER NOTIFICATION DEBUG", {
            ...orderNotificationDebug,
            exists: !existingNotificationSnap.empty,
          });

          if (!existingNotificationSnap.empty) {
            console.log("📦 ORDER NOTIFICATION DEBUG", {
              skipped: true,
              reason: "duplicate notificationKey",
              ...orderNotificationDebug,
            });
            continue;
          }

          await db.collection("notifications").add({
            recipientUserId: ownerUid,
            userId: ownerUid,
            type: "new_order",
            title: "New paid order 🛒",
            body: "A customer has completed payment for a new order.",

            orderId: orderNotificationDebug.orderId,
            sellerOrderId: orderNotificationDebug.sellerOrderId,
            businessId: orderNotificationDebug.businessId,
            notificationKey,
            payload: orderNotificationDebug,

            isRead: false,
            createdAt: admin.firestore.FieldValue.serverTimestamp(),
          });

          try {
            const recipientSnap = await db.collection("users").doc(ownerUid).get();
            const token = recipientSnap.data()?.fcmToken || businessToken || null;
            const message = {
              token,
              notification: {
                title: "New paid order 🛒",
                body: "A customer has completed payment for a new order.",
              },
              data: {
                type: orderNotificationDebug.type,
                orderId: orderNotificationDebug.orderId,
                sellerOrderId: orderNotificationDebug.sellerOrderId,
                businessId: orderNotificationDebug.businessId,
                recipientUserId: orderNotificationDebug.recipientUserId,
                notificationKey: orderNotificationDebug.notificationKey,
              },
              android: {
                priority: "high",
                notification: {
                  sound: "default",
                  channelId: "high_importance_channel",
                },
              },
              apns: {
                headers: {
                  "apns-priority": "10",
                },
                payload: {
                  aps: {
                    alert: {
                      title: "New paid order 🛒",
                      body: "A customer has completed payment for a new order.",
                    },
                    sound: "default",
                    badge: 1,
                    "interruption-level": "time-sensitive",
                  },
                },
              },
            };

            console.log("📨 FCM PAYLOAD DEBUG", message);
            console.log("🔔 PUSH TYPE = new_paid_order");
            console.log("🔔 RECIPIENT UID =", ownerUid);
            console.log("🔔 BUSINESS ID =", businessId);
            console.log("🔔 TOKEN FOUND =", !!token);

            if (token) {
              console.log("🔔 ABOUT TO SEND PUSH");
              console.log("🔔 PUSH TOKEN", token);
              console.log("🔔 PUSH PAYLOAD", message);
              const response = await safeMessagingSend(message, {
                functionName: "verifyPaymentByOrderId",
                notificationType: "new_order",
                orderId: orderNotificationDebug.orderId,
                sellerOrderId: orderNotificationDebug.sellerOrderId,
                businessId: orderNotificationDebug.businessId,
                recipientUserId: orderNotificationDebug.recipientUserId,
              });
              if (response) {
                console.log("✅ PUSH SENT SUCCESS", response);
              }
            } else {
              console.error("❌ PUSH SEND FAILED", "missing token");
            }
          } catch (error) {
            console.error("❌ PUSH SEND FAILED", error);
          }
        } else {
          console.log('❌ PUSH SEND FAILED', 'new_paid_order ownerUid missing');
        }
      }

      try {
        await sendExternalOrderNotifications({
          orderId: safeOrderId,
          orderData,
          source: "verifyPaymentByOrderId",
          paymentId: result?.paymentId || orderData?.payment?.paymentId || null,
          userId: orderData.buyerUid || orderData.userId || auth.uid,
        });
      } catch (e) {
        console.error("External order notification failed:", e);
      }

      if (paymentCallbackClaim) {
        await completePaymentCallback({
          ref: paymentCallbackClaim.ref,
          ownerToken: paymentCallbackClaim.ownerToken,
          result: { status: "committed", orderId: safeOrderId },
        });
      }

      return {
        success: true,
        orderId: safeOrderId,
        cartReconciled: cartReconciliation.reconciled === true,
        paymentId: result?.paymentId || null,
        sellerOrderIds,
        inventoryStatus: paymentCallbackClaim ? "committed" : "not_applicable",
      };
    } catch (error) {
      logger.error("❌ verifyPaymentByOrderId ERROR", {
        message: error?.message || String(error),
        stack: error?.stack || null,
      });

      if (error instanceof HttpsError) {
        throw error;
      }

      throw new HttpsError("internal", error?.message || "Verify failed");
    }
  }
);
exports.verifyPayment = onCall(
  {
    region: "europe-west3",
    timeoutSeconds: 60,
    memory: "256MiB",
    secrets: [
      IYZICO_API_KEY,
      IYZICO_SECRET_KEY,
      resendApiKey,
      ORDER_EXTERNAL_NOTIFICATIONS_ENABLED,
    ],
  },
  async (request) => {
    try {
      const auth = request.auth;
      if (!auth?.uid) {
        throw new HttpsError("unauthenticated", "Login required.");
      }

      logger.info("VERIFY_PAYMENT_REQUEST", {
        requestData: request.data,
      });

      const { orderId } = request.data || {};
      if (!orderId) {
        throw new HttpsError("invalid-argument", "Missing orderId");
      }

      logger.info("VERIFY_PAYMENT_ORDERID", {
        orderId,
      });

      const db = admin.firestore();
      logger.info("VERIFY_FIRESTORE_LOOKUP", {
        collection: "orders",
        orderId,
      });
      const orderRef = db.collection("orders").doc(orderId);
      const orderSnap = await orderRef.get();
      let paymentTransactionIds = [];
      let paymentTransactionId = null;

      if (!orderSnap.exists) {
        logger.error("VERIFY_ORDER_NOT_FOUND", {
          orderId,
        });
        throw new HttpsError("not-found", "Order not found");
      }

      logger.info("VERIFY_PAYMENT_ORDERID", {
        orderId,
      });

      logger.info("VERIFY_FIRESTORE_LOOKUP", {
        collection: "orders",
        orderId,
      });

      const orderData = orderSnap.data() || {};
      const token = orderData.payment?.checkoutToken;

      if (!token) {
        throw new HttpsError(
          "failed-precondition",
          "Missing payment token in order"
        );
      }

      // =========================
      // 💳 VERIFY WITH IYZICO
      // =========================
      const iyzi = new Iyzipay({
        apiKey: IYZICO_API_KEY.value(),
        secretKey: IYZICO_SECRET_KEY.value(),
        uri: "https://sandbox-api.iyzipay.com",
      });

      const result = await new Promise((resolve, reject) => {
        iyzi.checkoutForm.retrieve({ token }, (err, res) => {
          if (err) return reject(err);
          return resolve(res);
        });
      });

      if (!result || result.status !== "success") {
        throw new HttpsError(
          "failed-precondition",
          "Payment not successful"
        );
      }

      paymentTransactionIds = extractPaymentTransactionIds(
        result?.itemTransactions
      );
      paymentTransactionId =
        paymentTransactionIds.length > 0
          ? paymentTransactionIds[0]
          : result?.paymentTransactionId?.toString?.() ||
          result?.paymentTransactionId ||
          null;

      console.log("💳 PAYMENT TRANSACTION ID", paymentTransactionId);
      if (!paymentTransactionId) {
        console.warn("⚠️ Missing paymentTransactionId");
      }

      // 🔁 جلوگیری از دوباره پرداخت
      let appointmentFinancial = null;
      let appointmentFinancialError = null;
      let resolvedServiceCategory = null;
      if (
        orderData.payment?.status === "paid" &&
        ![FINANCIAL_STATUS.PENDING, FINANCIAL_STATUS.REQUIRES_REPAIR].includes(
          normalizeLower(orderData.financialStatus)
        )
      ) {

        if (orderData.type === "appointment") {
          const appointmentCollection = appointmentCollectionForOrder(orderData);
          const appointmentId = orderData.appointmentId || null;

          if (appointmentCollection === "vet_appointments" && appointmentId) {
            const appointmentSnap = await db
              .collection(appointmentCollection)
              .doc(appointmentId)
              .get();

            if (appointmentSnap.exists) {
              await syncVetPatientVisitAfterPaid({
                db,
                appointmentId,
                appointmentData: appointmentSnap.data() || {},
              });
            }
          }
        }

        return {
          success: true,
          alreadyPaid: true,
          type: orderData.type || null,
          appointmentCollection: orderData.type === "appointment"
            ? appointmentCollectionForOrder(orderData)
            : null,
          appointmentType: orderData.appointmentType || null,
          appointmentId: orderData.type === "appointment"
            ? orderData.appointmentId || null
            : null,
          sellerOrderIds: orderData.sellerOrderIds || [],
        };
      }

      if (orderData.type === "appointment") {
        const appointmentId = orderData.appointmentId;
        const appointmentCollection = appointmentCollectionForOrder(orderData);

        if (!appointmentId) {
          throw new HttpsError(
            "failed-precondition",
            "Missing appointmentId in order"
          );
        }

        const appointmentRef = db
          .collection(appointmentCollection)
          .doc(appointmentId);
        const appointmentSnap = await appointmentRef.get();

        if (!appointmentSnap.exists) {
          throw new HttpsError("not-found", "Appointment not found");
        }

        const appointmentData = appointmentSnap.data() || {};
        const paidAmount = positiveFinancialNumber(
          result.paidPrice,
          result.price,
          orderData.pricing?.grandTotal,
          appointmentData.price,
          appointmentData.servicePrice
        );

        if (!paidAmount) {
          throw new HttpsError(
            "failed-precondition",
            "Verified payment amount is missing or invalid"
          );
        }

        if (appointmentCollection === "vet_appointments") {

          let rawServiceCategory =
            appointmentData.serviceCategory ||
            appointmentData.category ||
            null;

          // Try to resolve the category from the business service document.
          if (
            !rawServiceCategory &&
            appointmentData.businessId &&
            appointmentData.serviceId
          ) {
            const serviceSnap = await db
              .collection("businesses")
              .doc(appointmentData.businessId)
              .collection("services")
              .doc(appointmentData.serviceId)
              .get();

            if (serviceSnap.exists) {
              const serviceData = serviceSnap.data() || {};

              rawServiceCategory =
                serviceData.serviceCategory ||
                serviceData.category ||
                null;
            }
          }

          resolvedServiceCategory =
            normalizeLower(rawServiceCategory) === "surgery"
              ? "surgery"
              : "default";

        }

        try {
          appointmentFinancial = await calculateAppointmentFinancial({
            collectionName: appointmentCollection,
            record: appointmentData,
            paidAmount,
            resolvedVetServiceCategory: resolvedServiceCategory,
          });
          assertVerifiedCanonicalFinancial(appointmentFinancial);
        } catch (financialError) {
          appointmentFinancialError = financialError;
          logger.error("iyzico_paid_financial_snapshot_failed", {
            orderId,
            appointmentId,
            appointmentCollection,
            message: financialError?.message || String(financialError),
          });
        }

        logger.info("paid_appointment_financial_snapshot_calculated", {
          appointmentId,
          appointmentCollection,
          sector: appointmentFinancial?.sector || null,
          financialVersion: appointmentFinancial?.version || null,
          financialStatus: appointmentFinancial
            ? FINANCIAL_STATUS.VERIFIED
            : FINANCIAL_STATUS.REQUIRES_REPAIR,
        });
        const appointmentStatus = appointmentData.status || "pending";
        const appointmentPaymentPolicy = resolveAppointmentPaymentPolicy(
          appointmentData
        );
        const deadlineMillis = toMillisSafe(
          appointmentData.paymentDeadlineAt || null
        );

        if (appointmentStatus !== "awaiting_payment") {
          throw new HttpsError(
            "failed-precondition",
            `Appointment is not awaiting payment: ${appointmentStatus}`
          );
        }

        if (!appointmentPaymentPolicy.requiresPayment) {
          throw new HttpsError(
            "failed-precondition",
            "Appointment does not require payment"
          );
        }

        if (deadlineMillis && deadlineMillis < Date.now()) {
          throw new HttpsError(
            "failed-precondition",
            "Payment window expired"
          );
        }
      }

      // =========================
      // ✅ UPDATE ORDER
      // =========================
      await orderRef.update({
        "payment.status": "paid",
        paymentStatus: "paid",
        status: "paid",
        "payment.paymentId": result.paymentId || null,
        "payment.paymentProvider": "iyzico",
        "payment.paidPrice": result.paidPrice || null,
        "payment.price": result.price || null,
        "payment.conversationId": result.conversationId || orderData.payment?.conversationId || null,
        "payment.paymentTransactionId": paymentTransactionId || null,
        "payment.paymentTransactionIds": paymentTransactionIds,
        "payment.iyzicoPaymentTransactionId": paymentTransactionId || null,
        "payment.currency": result.currency || orderData.payment?.currency || orderData.currency || "TRY",
        "payment.finalizationStatus": "completed",
        "payment.finalizationCompletedAt": admin.firestore.FieldValue.serverTimestamp(),
        ...(orderData.type === "appointment"
          ? {
            financialStatus: appointmentFinancial
              ? FINANCIAL_STATUS.VERIFIED
              : FINANCIAL_STATUS.REQUIRES_REPAIR,
          }
          : {}),
        paidAt: admin.firestore.FieldValue.serverTimestamp(),
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });

      // =========================
      // 🔥 UPDATE APPOINTMENT + NOTIF + FCM
      // =========================
      if (orderData.type === "appointment") {
        const appointmentId = orderData.appointmentId;
        const appointmentCollection = appointmentCollectionForOrder(orderData);

        if (appointmentId) {
          const appointmentRef = db
            .collection(appointmentCollection)
            .doc(appointmentId);

          const appointmentSnap = await appointmentRef.get();
          const appointmentData = appointmentSnap.exists
            ? appointmentSnap.data() || {}
            : {};
          const payoutTimestamp =
            admin.firestore.FieldValue.serverTimestamp();

          await appointmentRef.update({
            paymentStatus: "paid",
            status: "confirmed_paid",
            ...(appointmentCollection === "vet_appointments"
              ? { serviceCategory: resolvedServiceCategory }
              : {}),
            ...(appointmentFinancial ? { financial: appointmentFinancial } : {}),
            financialStatus: appointmentFinancial
              ? FINANCIAL_STATUS.VERIFIED
              : FINANCIAL_STATUS.REQUIRES_REPAIR,
            ...(appointmentFinancialError
              ? {
                settlement: {
                  ...(appointmentData.settlement || {}),
                  status: "blocked",
                  failureCode: "FINANCIAL_REPAIR_REQUIRED",
                  failureMessage:
                    appointmentFinancialError.message ||
                    String(appointmentFinancialError),
                  updatedAt: admin.firestore.FieldValue.serverTimestamp(),
                },
              }
              : {}),
            "marketplace.lifecycleStatus": buildMarketplaceStatus("confirmed_paid"),
            "marketplace.pendingAction": false,
            "marketplace.updatedAt": new Date().toISOString(),
            "marketplace.lastStatusChangedBy": auth.uid,
            "marketplace.lastStatusChangedAt": new Date().toISOString(),
            "invoice.pricing": appointmentInvoicePricingSnapshot({
              price: result.paidPrice || result.price || appointmentData.price || 0,
            }),

            paidAt: payoutTimestamp,
            updatedAt: admin.firestore.FieldValue.serverTimestamp(),
            paymentId: result.paymentId || null,
            iyzicoPaymentId: result.paymentId || null,
            paymentTransactionId: paymentTransactionId || null,
            paymentTransactionIds,
            iyzicoPaymentTransactionId: paymentTransactionId || null,
            conversationId:
              result.conversationId || orderData.payment?.conversationId || null,
            orderId: orderId || null,
            checkoutToken: orderData.payment?.checkoutToken || null,
            "payment.finalizationStatus": "completed",
            "payment.finalizationCompletedAt": payoutTimestamp,
          });

          if (!appointmentFinancialError) try {
            await settlePayable({
              db,
              sector:
                payoutEngine.getPayoutSectorAdapterByCollection(
                  appointmentCollection
                ).sector,
              recordRef: appointmentRef,
              actor: { type: "system", id: "iyzico_settlement" },
            });
          } catch (settlementError) {
            logger.error("settlement_retryable_failure", {
              orderId,
              appointmentId,
              message: settlementError?.message || String(settlementError),
            });
          }

          // 🎯 پیدا کردن گیرنده (vet)
          const targetBusinessId =
            orderData.businessId ||
            appointmentData.businessId ||
            appointmentData.vetId ||
            null;
          let recipientUserId = targetBusinessId;
          if (targetBusinessId) {
            try {
              const businessSnap = await db
                .collection("businesses")
                .doc(targetBusinessId)
                .get();
              const businessData = businessSnap.data() || {};
              recipientUserId =
                businessData.ownerUid ||
                businessData.uid ||
                targetBusinessId;
            } catch (error) {
              logger.warn("⚠️ Payment recipient owner lookup failed", {
                businessId: targetBusinessId,
                message: error?.message || String(error),
              });
            }
          }
          const isHotelBooking = appointmentCollection === "hotel_bookings";

          logger.info("🐾 Appointment marked as PAID", {
            appointmentId,
            recipientUserId,
          });

          if (appointmentCollection === "vet_appointments") {
            await syncVetPatientVisitAfterPaid({
              db,
              appointmentId,
              appointmentData,
            });
          }

          if (recipientUserId) {
            // =========================
            // 🟣 1. SAVE IN-APP NOTIFICATION
            // =========================
            await db.collection("notifications").add({
              type: isHotelBooking
                ? "hotel_booking_payment_completed"
                : "appointment_paid",
              recipientUserId: recipientUserId,
              senderUserId: auth.uid,
              title: isHotelBooking
                ? "Hotel Payment Completed"
                : "Payment Completed",
              body: `${appointmentData.petName ||
                appointmentData.dogName ||
                (isHotelBooking ? "Booking" : "Appointment")
                } payment completed successfully`,
              appointmentId: appointmentId,
              bookingId: isHotelBooking ? appointmentId : null,
              appointmentCollection,
              appointmentType: orderData.appointmentType || null,
              orderId: orderId,
              isRead: false,
              createdAt: admin.firestore.FieldValue.serverTimestamp(),
            });

            // =========================
            // 🔔 2. SEND PUSH (FCM)
            // =========================
            const userSnap = await db
              .collection("users")
              .doc(recipientUserId)
              .get();

            const fcmToken = userSnap.data()?.fcmToken;

            if (fcmToken) {
              logger.info("🔔 Playdate/PetTaxi reference sound payload attached", {
                type: isHotelBooking
                  ? "hotel_booking_payment_completed"
                  : "appointment_paid",
                recipientUserId,
                appointmentId,
              });
              const paymentPushMessage = {
                token: fcmToken,
                notification: {
                  title: "Payment Completed",
                  body: isHotelBooking
                    ? "Hotel booking has been paid"
                    : "Appointment has been paid",
                },
                data: {
                  type: isHotelBooking
                    ? "hotel_booking_payment_completed"
                    : "appointment_paid",
                  appointmentId: appointmentId,
                  bookingId: isHotelBooking ? appointmentId : "",
                  appointmentCollection,
                  appointmentType: orderData.appointmentType || "",
                },
                android: {
                  priority: "high",
                  notification: {
                    sound: "default",
                    channelId: "high_importance_channel",
                  },
                },
                apns: {
                  headers: { "apns-priority": "10" },
                  payload: {
                    aps: {
                      alert: {
                        title: "Payment Completed",
                        body: isHotelBooking
                          ? "Hotel booking has been paid"
                          : "Appointment has been paid",
                      },
                      sound: "default",
                      badge: 1,
                      "interruption-level": "time-sensitive",
                    },
                  },
                },
              };

              const fcmResponse = await safeMessagingSend(paymentPushMessage, {
                functionName: "verifyPayment",
                notificationType: isHotelBooking
                  ? "hotel_booking_payment_completed"
                  : "appointment_paid",
                recipientUserId,
                appointmentId,
                appointmentCollection,
              });

              if (fcmResponse) {
                logger.info("🔔 FCM sent", {
                  recipientUserId,
                  appointmentId,
                  soundEnabled: true,
                });
              }
            } else {
              logger.warn("⚠️ No FCM token found", {
                recipientUserId,
              });
            }
          } else {
            logger.warn("⚠️ No recipientUserId", {
              appointmentId,
            });
          }

          if (isHotelBooking && appointmentData.userId) {
            await createNotification(db, {
              type: "hotel_booking_response",
              recipientUserId: appointmentData.userId,
              userId: appointmentData.userId,
              senderUserId: recipientUserId || "system",
              businessId: appointmentData.businessId || targetBusinessId,
              appointmentId,
              bookingId: appointmentId,
              appointmentCollection,
              status: "confirmed_paid",
              title: "Hotel Payment Completed",
              body: `${appointmentData.serviceTitle || "Hotel stay"} is confirmed and paid`,
            });
          }
        }
      }

      if (orderData.type === "appointment") {
        try {
          await sendExternalOrderNotifications({
            orderId,
            orderData,
            source: "verifyPayment",
            paymentId: result?.paymentId || orderData?.payment?.paymentId || null,
            userId: orderData.buyerUid || orderData.userId || auth.uid,
          });
        } catch (e) {
          console.error("External order notification failed:", e);
        }

        return {
          success: true,
          type: "appointment",
          appointmentCollection: appointmentCollectionForOrder(orderData),
          appointmentType: orderData.appointmentType || null,
          appointmentId: orderData.appointmentId || null,
          sellerOrderIds: [],
        };
      }

      // =========================
      // 💰 SELLER ORDERS UPDATE
      // =========================
      const sellerOrdersSnap = await db
        .collection("sellerOrders")
        .where("rootOrderId", "==", orderId)
        .get();

      const batch = db.batch();
      const sellerOrderIds = [];

      for (const doc of sellerOrdersSnap.docs) {
        const data = doc.data() || {};
        sellerOrderIds.push(doc.id);

        const sellerNetAmount =
          data.financial?.sellerNetAmount ?? null;

        batch.update(doc.ref, {
          status: "paid",
          paymentStatus: "paid",
          payment: {
            ...(data.payment || {}),
            status: "paid",
            provider: "iyzico",
            paymentProvider: data.payment?.paymentProvider || "iyzico",
            paymentId: result.paymentId || null,
            paidPrice: result.paidPrice || null,
            price: result.price || null,
            conversationId: result.conversationId || orderData.payment?.conversationId || null,
            currency: result.currency || orderData.payment?.currency || orderData.currency || "TRY",
            paymentTransactionId: paymentTransactionId || null,
            paymentTransactionIds: paymentTransactionIds,
            iyzicoPaymentTransactionId: paymentTransactionId || null,
          },
          "payout.status": "pending",
          "payout.amount": sellerNetAmount,
          "payout.requestedAt":
            admin.firestore.FieldValue.serverTimestamp(),
          "payout.updatedAt":
            admin.firestore.FieldValue.serverTimestamp(),
          financialStatus: hasCompleteFinancial(data.financial)
            ? FINANCIAL_STATUS.VERIFIED
            : FINANCIAL_STATUS.REQUIRES_REPAIR,
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        });
      }

      await batch.commit();
      await orderRef.update({
        financialStatus: sellerOrdersSnap.docs.every((doc) =>
          hasCompleteFinancial(doc.data()?.financial)
        )
          ? FINANCIAL_STATUS.VERIFIED
          : FINANCIAL_STATUS.REQUIRES_REPAIR,
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
      });

      for (const doc of sellerOrdersSnap.docs) {
        const sellerOrderId = doc.id;
        const sellerData = doc.data() || {};
        const businessId = sellerData.businessId || sellerData.shopId || null;

        const businessSnap = businessId
          ? await db.collection("businesses").doc(String(businessId)).get()
          : null;
        const businessData = businessSnap?.exists ? businessSnap.data() || {} : {};
        const ownerUid = businessSnap?.exists
          ? businessData.ownerUid || businessData.uid || null
          : null;
        const businessToken = businessData.fcmToken || null;

        console.log("🔔 PUSH TYPE = new_paid_order");
        console.log("🔔 RECIPIENT UID =", ownerUid);
        console.log("🔔 BUSINESS ID =", businessId);

        if (ownerUid) {
          const notificationKey = `new_order_${sellerOrderId}`;
          const orderNotificationDebug = {
            type: "new_order",
            orderId: String(orderId || ""),
            sellerOrderId: String(sellerOrderId || ""),
            businessId: String(businessId || ""),
            recipientUserId: String(ownerUid || ""),
            notificationKey,
          };
          const existingNotificationSnap = await db
            .collection("notifications")
            .where("notificationKey", "==", notificationKey)
            .limit(1)
            .get();

          console.log("📦 ORDER NOTIFICATION DEBUG", {
            ...orderNotificationDebug,
            exists: !existingNotificationSnap.empty,
          });

          if (!existingNotificationSnap.empty) {
            console.log("📦 ORDER NOTIFICATION DEBUG", {
              skipped: true,
              reason: "duplicate notificationKey",
              ...orderNotificationDebug,
            });
            continue;
          }

          await db.collection("notifications").add({
            recipientUserId: ownerUid,
            userId: ownerUid,
            type: "new_order",
            title: "New paid order 🛒",
            body: "A customer has completed payment for a new order.",
            orderId: orderNotificationDebug.orderId,
            sellerOrderId: orderNotificationDebug.sellerOrderId,
            businessId: orderNotificationDebug.businessId,
            notificationKey,
            payload: orderNotificationDebug,
            isRead: false,
            createdAt: admin.firestore.FieldValue.serverTimestamp(),
          });

          try {
            const recipientSnap = await db
              .collection("users")
              .doc(String(ownerUid))
              .get();
            const token = recipientSnap.data()?.fcmToken || businessToken || null;
            const message = {
              token,
              notification: {
                title: "New paid order 🛒",
                body: "A customer has completed payment for a new order.",
              },
              data: {
                type: orderNotificationDebug.type,
                orderId: orderNotificationDebug.orderId,
                sellerOrderId: orderNotificationDebug.sellerOrderId,
                businessId: orderNotificationDebug.businessId,
                recipientUserId: orderNotificationDebug.recipientUserId,
                notificationKey: orderNotificationDebug.notificationKey,
              },
              android: {
                priority: "high",
                notification: {
                  sound: "default",
                  channelId: "high_importance_channel",
                },
              },
              apns: {
                headers: {
                  "apns-priority": "10",
                },
                payload: {
                  aps: {
                    alert: {
                      title: "New paid order 🛒",
                      body: "A customer has completed payment for a new order.",
                    },
                    sound: "default",
                    badge: 1,
                    "interruption-level": "time-sensitive",
                  },
                },
              },
            };

            console.log("📨 FCM PAYLOAD DEBUG", message);
            console.log("🔔 TOKEN FOUND =", !!token);

            if (token) {
              console.log("🔔 ABOUT TO SEND PUSH");
              console.log("🔔 PUSH TOKEN", token);
              console.log("🔔 PUSH PAYLOAD", message);
              const response = await safeMessagingSend(message, {
                functionName: "verifyPayment",
                notificationType: "new_order",
                orderId: orderNotificationDebug.orderId,
                sellerOrderId: orderNotificationDebug.sellerOrderId,
                businessId: orderNotificationDebug.businessId,
                recipientUserId: orderNotificationDebug.recipientUserId,
              });
              if (response) {
                console.log("✅ PUSH SENT SUCCESS", response);
              }
            } else {
              console.error("❌ PUSH SEND FAILED", "missing token");
            }
          } catch (error) {
            console.error("❌ PUSH SEND FAILED", error);
          }
        } else {
          console.log("❌ PUSH SEND FAILED", "new_paid_order ownerUid missing");
        }
      }

      try {
        await sendExternalOrderNotifications({
          orderId,
          orderData,
          source: "verifyPayment",
          paymentId: result?.paymentId || orderData?.payment?.paymentId || null,
          userId: orderData.buyerUid || orderData.userId || auth.uid,
        });
      } catch (e) {
        console.error("External order notification failed:", e);
      }

      return {
        success: true,
        sellerOrderIds,
      };
    } catch (error) {
      console.error("❌ verifyPayment INTERNAL CRASH", error);
      logger.error("❌ verifyPayment ERROR", {
        message: error?.message || String(error),
        stack: error?.stack || null,
      });

      if (error instanceof HttpsError) {
        throw error;
      }

      throw new HttpsError(
        "internal",
        error?.message || "Verify failed"
      );
    }
  }
);

exports.verifyHotelBookingPayment = exports.verifyPayment;

exports.expireAwaitingAppointmentPayments = onSchedule(
  {
    region: "europe-west3",
    schedule: "every 5 minutes",
    timeZone: "Europe/Istanbul",
  },
  async () => {
    const now = admin.firestore.Timestamp.now();

    const snap = await db
      .collection("vet_appointments")
      .where("status", "==", "awaiting_payment")
      .where("paymentDeadlineAt", "<", now)
      .orderBy("paymentDeadlineAt")
      .limit(100)
      .get();

    if (snap.empty) {
      logger.info("🩺 PAYMENT EXPIRE JOB: no overdue appointments");
      return;
    }

    const batch = db.batch();
    const targets = [];

    for (const doc of snap.docs) {
      const data = doc.data() || {};
      const appointmentId = doc.id;
      const businessId = data.businessId || null;
      const userId = data.userId || data.buyerUid || null;

      console.log("🩺 PAYMENT EXPIRED", {
        appointmentId,
        businessId,
        userId,
        currentStatus: data.status || null,
        paymentDeadlineAt: data.paymentDeadlineAt || null,
      });
      console.log("🩺 SLOT RELEASED", {
        appointmentId,
      });

      batch.update(doc.ref, {
        status: "payment_expired",
        paymentStatus: "expired",
        updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        statusUpdatedAt: admin.firestore.FieldValue.serverTimestamp(),
        statusUpdatedBy: "system",
        paymentExpiredAt: admin.firestore.FieldValue.serverTimestamp(),
        lastStatusChange: {
          from: "awaiting_payment",
          to: "payment_expired",
          by: "system",
          at: admin.firestore.FieldValue.serverTimestamp(),
        },
      });

      targets.push({
        appointmentId,
        businessId,
        userId,
        serviceTitle: data.serviceTitle || "Service",
      });
    }

    await batch.commit();

    for (const target of targets) {
      try {
        if (target.userId) {
          await db.collection("notifications").add({
            type: "appointment_payment_expired",
            recipientUserId: target.userId,
            senderUserId: "system",
            appointmentId: target.appointmentId,
            status: "payment_expired",
            title: "Payment window expired",
            body: `${target.serviceTitle} payment window expired`,
            isRead: false,
            createdAt: admin.firestore.FieldValue.serverTimestamp(),
          });

          const userSnap = await db.collection("users").doc(target.userId).get();
          const fcmToken = userSnap.data()?.fcmToken;

          if (fcmToken) {
            logger.info("🔔 Playdate/PetTaxi reference sound payload attached", {
              type: "appointment_payment_expired",
              recipientUserId: target.userId,
              appointmentId: target.appointmentId,
            });
            await admin.messaging().send({
              token: fcmToken,
              notification: {
                title: "Payment window expired",
                body: `${target.serviceTitle} payment window expired`,
              },
              data: {
                type: "appointment_payment_expired",
                appointmentId: target.appointmentId,
                status: "payment_expired",
              },
              android: {
                priority: "high",
                notification: {
                  sound: "default",
                  channelId: "high_importance_channel",
                },
              },
              apns: {
                headers: { "apns-priority": "10" },
                payload: {
                  aps: {
                    alert: {
                      title: "Payment window expired",
                      body: `${target.serviceTitle} payment window expired`,
                    },
                    sound: "default",
                    badge: 1,
                    "interruption-level": "time-sensitive",
                  },
                },
              },
            });
            logger.info("🔔 Push send success", {
              type: "appointment_payment_expired",
              recipientUserId: target.userId,
              soundEnabled: true,
            });
          } else {
            logger.warn("⚠️ Push token missing", {
              type: "appointment_payment_expired",
              recipientUserId: target.userId,
            });
          }
        }

        if (target.businessId) {
          const businessSnap = await db
            .collection("businesses")
            .doc(target.businessId)
            .get();
          const businessData = businessSnap.data() || {};
          const businessOwnerUid = businessData.ownerUid || businessData.uid || target.businessId;

          await db.collection("notifications").add({
            type: "vet_appointment_payment_expired",
            recipientUserId: businessOwnerUid,
            senderUserId: "system",
            appointmentId: target.appointmentId,
            status: "payment_expired",
            title: "Appointment payment expired",
            body: `${target.serviceTitle} payment window expired`,
            isRead: false,
            createdAt: admin.firestore.FieldValue.serverTimestamp(),
          });

          const vetUserSnap = await db.collection("users").doc(businessOwnerUid).get();
          const vetToken = vetUserSnap.data()?.fcmToken;

          if (vetToken) {
            await safeSendPush({
              token: vetToken,
              userId: businessOwnerUid,
              payload: {
                notification: {
                  title: "Appointment payment expired",
                  body: `${target.serviceTitle} payment window expired`,
                },
                data: {
                  type: "vet_appointment_payment_expired",
                  appointmentId: target.appointmentId,
                  status: "payment_expired",
                },
                android: { priority: "high" },
              },
            });
          }
        }
      } catch (error) {
        logger.error("❌ payment expiry notification failed", {
          appointmentId: target.appointmentId,
          message: error?.message || String(error),
        });
      }
    }
  }
);

