exports.sendTelegramMessage = onCall(
  {
    region: "europe-west1",
    secrets: [TELEGRAM_BOT_TOKEN],
  },
  async (request) => {
    if (!request.auth) {
      throw new HttpsError("unauthenticated", "Login required");
    }

    const { chatId, text } = request.data || {};

    if (!chatId || !text) {
      throw new HttpsError("invalid-argument", "chatId and text are required");
    }

    const token = TELEGRAM_BOT_TOKEN.value();

    const response = await fetch(
      `https://api.telegram.org/bot${token}/sendMessage`,
      {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          chat_id: chatId,
          text,
        }),
      }
    );

    const result = await response.json();

    if (!response.ok || result.ok !== true) {
      throw new HttpsError(
        "internal",
        result.description || "Telegram send failed"
      );
    }

    return {
      ok: true,
      result,
    };
  }
);

// ============================================================================
// CREATOR REFERRAL ENGINE — SPRINT 1 (Creator Foundation)
//
// See docs/architecture/creator-referral-engine.md for the full target
// architecture and docs/SPRINT1_REPORT.md for exactly what this sprint
// covers. Intentionally minimal: profile bootstrap, referral code
// assignment, and enable/disable. No applications, no admin review UI, no
// click tracking, no attribution, no rewards, no payouts — all deferred to
// later sprints per the ADR.
//
// Every function below is admin-only (isAdminUser) and writes exclusively
// through the Admin SDK, which bypasses firestore.rules entirely — this is
// what makes the SEC-1 fix in firestore.rules meaningful: the `creator` map
// is reachable only from here, never from a client write.
// ============================================================================

const CREATOR_CODE_ALPHABET = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789"; // no ambiguous 0/O/1/I

function normalizeCreatorUid(value) {
  return typeof value === "string" ? value.trim() : "";
}

function randomCreatorCodeSuffix(length) {
  let out = "";
  for (let i = 0; i < length; i++) {
    out += CREATOR_CODE_ALPHABET[crypto.randomInt(CREATOR_CODE_ALPHABET.length)];
  }
  return out;
}

function creatorCodeBase(username) {
  const cleaned = String(username || "")
    .toUpperCase()
    .replace(/[^A-Z0-9]/g, "")
    .slice(0, 10);
  return cleaned || "CREATOR";
}

async function requireCreatorAdmin(auth) {
  if (!auth?.uid) {
    throw new HttpsError("unauthenticated", "Login required.");
  }
  if (!(await isAdminUser(db, auth.uid))) {
    throw new HttpsError("permission-denied", "Admin access required.");
  }
}

/**
 * Bootstraps an inactive creator profile on users/{uid}.creator.
 * Idempotent: calling this twice on an existing profile is a no-op, not an
 * error, matching this codebase's established idempotency conventions
 * (e.g. createWebSubscriptionCheckout's existing-order handling).
 */
exports.createCreatorProfile = onCall(
  { region: "europe-west3" },
  async (request) => {
    await requireCreatorAdmin(request.auth);

    const targetUid = normalizeCreatorUid(request.data?.uid);
    if (!targetUid) {
      throw new HttpsError("invalid-argument", "uid required");
    }

    const userRef = db.collection("users").doc(targetUid);

    const result = await db.runTransaction(async (transaction) => {
      const snap = await transaction.get(userRef);
      if (!snap.exists) {
        throw new HttpsError("not-found", "Target user does not exist.");
      }
      const existing = snap.data()?.creator;
      if (existing) {
        return { status: existing.status || "inactive", alreadyExisted: true };
      }
      transaction.update(userRef, {
        creator: {
          enabled: false,
          status: "inactive",
          referralCode: null,
          createdAt: admin.firestore.FieldValue.serverTimestamp(),
          updatedAt: admin.firestore.FieldValue.serverTimestamp(),
        },
      });
      return { status: "inactive", alreadyExisted: false };
    });

    logger.info("creator_profile_created", {
      targetUid,
      adminUid: request.auth.uid,
      alreadyExisted: result.alreadyExisted,
    });

    return { uid: targetUid, status: result.status };
  }
);

/**
 * Generates and atomically assigns a unique, permanent referral code.
 * Uniqueness is enforced by using the code itself as the referralCodes
 * document ID and relying on transaction.create() to fail on collision —
 * the same idiom this codebase already uses for orders/{orderId} and
 * websub_{...} deterministic IDs.
 */
exports.assignReferralCode = onCall(
  { region: "europe-west3" },
  async (request) => {
    await requireCreatorAdmin(request.auth);

    const targetUid = normalizeCreatorUid(request.data?.uid);
    if (!targetUid) {
      throw new HttpsError("invalid-argument", "uid required");
    }

    const userRef = db.collection("users").doc(targetUid);
    const userSnap = await userRef.get();
    if (!userSnap.exists) {
      throw new HttpsError("not-found", "Target user does not exist.");
    }

    const existingCreator = userSnap.data()?.creator;
    if (!existingCreator) {
      throw new HttpsError(
        "failed-precondition",
        "createCreatorProfile must be called before assignReferralCode."
      );
    }
    if (existingCreator.referralCode) {
      // Codes are permanent (ADR Business Rules) — re-calling this is a
      // read, not a regeneration.
      return { uid: targetUid, referralCode: existingCreator.referralCode };
    }

    const base = creatorCodeBase(userSnap.data()?.username);
    let assignedCode = null;
    let lastError = null;

    for (let attempt = 0; attempt < 8 && !assignedCode; attempt++) {
      const suffixLength = attempt === 0 ? 2 : 4;
      const candidate = `${base}${randomCreatorCodeSuffix(suffixLength)}`;
      const codeRef = db.collection("referralCodes").doc(candidate);

      try {
        await db.runTransaction(async (transaction) => {
          const codeSnap = await transaction.get(codeRef);
          if (codeSnap.exists) {
            throw new HttpsError("already-exists", "collision");
          }
          transaction.create(codeRef, {
            creatorUid: targetUid,
            active: true,
            createdAt: admin.firestore.FieldValue.serverTimestamp(),
          });
          transaction.update(userRef, {
            "creator.referralCode": candidate,
            "creator.updatedAt": admin.firestore.FieldValue.serverTimestamp(),
          });
        });
        assignedCode = candidate;
      } catch (error) {
        lastError = error;
        if (error instanceof HttpsError && error.code === "already-exists") {
          continue; // collision — retry with a new random suffix
        }
        throw error;
      }
    }

    if (!assignedCode) {
      logger.warn("creator_referral_code_generation_exhausted", {
        targetUid,
        lastError: lastError?.message || String(lastError),
      });
      throw new HttpsError(
        "aborted",
        "Could not generate a unique referral code — please retry."
      );
    }

    logger.info("creator_referral_code_assigned", {
      targetUid,
      adminUid: request.auth.uid,
    });

    return { uid: targetUid, referralCode: assignedCode };
  }
);

/**
 * Activates a creator profile: flips creator.enabled true and
 * creator.status to "active". Requires a referral code to already exist —
 * a creator cannot be activated without a working referral link.
 */
exports.activateCreator = onCall(
  { region: "europe-west3" },
  async (request) => {
    await requireCreatorAdmin(request.auth);

    const targetUid = normalizeCreatorUid(request.data?.uid);
    if (!targetUid) {
      throw new HttpsError("invalid-argument", "uid required");
    }

    const userRef = db.collection("users").doc(targetUid);

    await db.runTransaction(async (transaction) => {
      const snap = await transaction.get(userRef);
      if (!snap.exists) {
        throw new HttpsError("not-found", "Target user does not exist.");
      }
      const creator = snap.data()?.creator;
      if (!creator) {
        throw new HttpsError(
          "failed-precondition",
          "createCreatorProfile must be called before activateCreator."
        );
      }
      if (!creator.referralCode) {
        throw new HttpsError(
          "failed-precondition",
          "assignReferralCode must be called before activateCreator."
        );
      }
      transaction.update(userRef, {
        "creator.enabled": true,
        "creator.status": "active",
        "creator.updatedAt": admin.firestore.FieldValue.serverTimestamp(),
      });
    });

    logger.info("creator_activated", {
      targetUid,
      adminUid: request.auth.uid,
    });

    return { uid: targetUid, enabled: true, status: "active" };
  }
);

/**
 * Deactivates a creator profile: flips creator.enabled false and
 * creator.status back to "inactive". Does NOT clear the referral code —
 * codes are permanent and history is never rewritten (ADR Principle 4),
 * only the active/enabled state changes.
 */
exports.deactivateCreator = onCall(
  { region: "europe-west3" },
  async (request) => {
    await requireCreatorAdmin(request.auth);

    const targetUid = normalizeCreatorUid(request.data?.uid);
    if (!targetUid) {
      throw new HttpsError("invalid-argument", "uid required");
    }

    const userRef = db.collection("users").doc(targetUid);

    await db.runTransaction(async (transaction) => {
      const snap = await transaction.get(userRef);
      if (!snap.exists) {
        throw new HttpsError("not-found", "Target user does not exist.");
      }
      const creator = snap.data()?.creator;
      if (!creator) {
        throw new HttpsError(
          "failed-precondition",
          "This user does not have a creator profile."
        );
      }
      transaction.update(userRef, {
        "creator.enabled": false,
        "creator.status": "inactive",
        "creator.updatedAt": admin.firestore.FieldValue.serverTimestamp(),
      });
    });

    logger.info("creator_deactivated", {
      targetUid,
      adminUid: request.auth.uid,
    });

    return { uid: targetUid, enabled: false, status: "inactive" };
  }
);

/**
 * Creates the one immutable attribution record for a referred user.
 * Validation and creation stay server-side so clients cannot forge creator
 * status, creator identity, or attribution timestamps.
 */
exports.attributeReferral = onCall(
  { region: "europe-west3" },
  async (request) => {
    const callerUid = request.auth?.uid;
    if (!callerUid) {
      throw new HttpsError("unauthenticated", "Login required.");
    }

    const referralCode = String(request.data?.referralCode || "")
      .trim()
      .toUpperCase();
    if (!referralCode) {
      throw new HttpsError("invalid-argument", "Referral code required.");
    }

    const codeRef = db.collection("referralCodes").doc(referralCode);
    const attributionRef = db.collection("referralAttributions").doc(callerUid);

    const result = await db.runTransaction(async (transaction) => {
      const codeSnap = await transaction.get(codeRef);
      if (!codeSnap.exists || codeSnap.data()?.active !== true) {
        throw new HttpsError("not-found", "Invalid referral code.");
      }

      const creatorUid = normalizeCreatorUid(codeSnap.data()?.creatorUid);
      if (!creatorUid || creatorUid === callerUid) {
        throw new HttpsError("failed-precondition", "Referral code unavailable.");
      }

      const creatorRef = db.collection("users").doc(creatorUid);
      const [creatorSnap, existingAttribution] = await Promise.all([
        transaction.get(creatorRef),
        transaction.get(attributionRef),
      ]);

      if (existingAttribution.exists) {
        return { alreadyAttributed: true };
      }

      const creator = creatorSnap.data()?.creator;
      if (
        !creatorSnap.exists ||
        creator?.enabled !== true ||
        creator?.status !== "active" ||
        creator?.referralCode !== referralCode
      ) {
        throw new HttpsError("failed-precondition", "Referral code unavailable.");
      }

      transaction.create(attributionRef, {
        referralCode,
        creatorUid,
        attributedAt: admin.firestore.FieldValue.serverTimestamp(),
        source: "code_entry",
        kind: "user",
        status: "pending",
      });

      return { alreadyAttributed: false };
    });

    logger.info("referral_attributed", {
      callerUid,
      referralCode,
      alreadyAttributed: result.alreadyAttributed,
    });

    return {
      attributed: !result.alreadyAttributed,
      alreadyAttributed: result.alreadyAttributed,
    };
  }
);

async function qualifyUserReferralOnAuthenticatedLogin(referredUid) {
  const attributionRef = db.collection("referralAttributions").doc(referredUid);
  const userRef = db.collection("users").doc(referredUid);

  return db.runTransaction(async (transaction) => {
    const [attributionSnap, userSnap] = await Promise.all([
      transaction.get(attributionRef),
      transaction.get(userRef),
    ]);

    if (!attributionSnap.exists) return { status: "not_attributed" };

    const attribution = attributionSnap.data() || {};
    if (attribution.kind !== "user") return { status: "not_user_lead" };
    if (attribution.status !== "pending") {
      return { status: attribution.status || "unknown" };
    }
    if (!userSnap.exists) return { status: "not_registered" };

    const ledgerRef = db.collection("creator_reward_ledger").doc(referredUid);
    const ledgerQuery = db
      .collection("creator_reward_ledger")
      .where("creatorUid", "==", attribution.creatorUid)
      .where("leadType", "==", "user");
    const [ledgerSnap, creatorLedgerSnap] = await Promise.all([
      transaction.get(ledgerRef),
      transaction.get(ledgerQuery),
    ]);
    const reward = rewardForLead("user", creatorLedgerSnap.size);

    if (!ledgerSnap.exists) {
      transaction.create(ledgerRef, {
        creatorUid: attribution.creatorUid,
        creatorCode: attribution.referralCode,
        referredUid,
        attributionId: attributionRef.id,
        leadType: "user",
        rewardAmount: reward.amount,
        rewardCurrency: "TRY",
        rewardRuleVersion: REWARD_RULE_VERSION,
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        status: "pending",
      });
    }

    transaction.update(attributionRef, {
      status: "qualified",
      qualifiedAt: admin.firestore.FieldValue.serverTimestamp(),
    });
    return { status: "qualified" };
  });
}

exports.qualifyUserReferralOnLogin = onCall(
  { region: "europe-west3" },
  async (request) => {
    const uid = request.auth?.uid;
    if (!uid) {
      throw new HttpsError("unauthenticated", "Login required.");
    }

    const result = await qualifyUserReferralOnAuthenticatedLogin(uid);
    logger.info("user_referral_qualification_checked", {
      uid,
      status: result.status,
    });
    return result;
  }
);

async function qualifyPartnerReferralForBusiness({ businessId, ownerUid }) {
  if (!businessId || !ownerUid) return { status: "missing_business_identity" };

  const attributionRef = db.collection("referralAttributions").doc(ownerUid);
  const businessRef = db.collection("businesses").doc(businessId);

  return db.runTransaction(async (transaction) => {
    const [attributionSnap, businessSnap] = await Promise.all([
      transaction.get(attributionRef),
      transaction.get(businessRef),
    ]);

    if (!attributionSnap.exists) return { status: "not_attributed" };

    const attribution = attributionSnap.data() || {};
    if (attribution.kind !== "business") return { status: "not_partner_lead" };
    if (attribution.status !== "pending") {
      return { status: attribution.status || "unknown" };
    }
    if (!businessSnap.exists) return { status: "business_not_found" };

    const business = businessSnap.data() || {};
    const verification = business.verification || {};
    const ready =
      business.status === "approved" &&
      verification.isVerified === true &&
      business.published === true;

    if (!ready) return { status: "partner_conditions_incomplete" };

    const ledgerRef = db.collection("creator_reward_ledger").doc(ownerUid);
    const ledgerQuery = db
      .collection("creator_reward_ledger")
      .where("creatorUid", "==", attribution.creatorUid)
      .where("leadType", "==", "partner");
    const [ledgerSnap, creatorLedgerSnap] = await Promise.all([
      transaction.get(ledgerRef),
      transaction.get(ledgerQuery),
    ]);
    const reward = rewardForLead("partner", creatorLedgerSnap.size);

    if (!ledgerSnap.exists) {
      transaction.create(ledgerRef, {
        creatorUid: attribution.creatorUid,
        creatorCode: attribution.referralCode,
        referredUid: ownerUid,
        attributionId: attributionRef.id,
        leadType: "partner",
        rewardAmount: reward.amount,
        rewardCurrency: "TRY",
        rewardRuleVersion: REWARD_RULE_VERSION,
        createdAt: admin.firestore.FieldValue.serverTimestamp(),
        status: "pending",
      });
    }

    transaction.update(attributionRef, {
      status: "qualified",
      qualifiedAt: admin.firestore.FieldValue.serverTimestamp(),
    });
    return { status: "qualified" };
  });
}

exports.qualifyPartnerReferralOnBusinessUpdate = onDocumentUpdated(
  { document: "businesses/{businessId}", region: "europe-west1" },
  async (event) => {
    const business = event.data?.after?.data() || {};
    const ownerUid = firstNonEmptyString(
      business.ownerUid,
      business.ownerId,
      business.uid
    );
    if (
      business.status !== "approved" ||
      business.verification?.isVerified !== true ||
      business.published !== true ||
      !ownerUid
    ) {
      return null;
    }

    const result = await qualifyPartnerReferralForBusiness({
      businessId: event.params.businessId,
      ownerUid,
    });
    logger.info("partner_referral_qualification_checked", {
      businessId: event.params.businessId,
      ownerUid,
      status: result.status,
    });
    return null;
  }
);

// ---------------------------------------------------------------------------
// Canonical business media (logo / cover / gallery)
// ---------------------------------------------------------------------------
// Thin wrapper only. All logic — ownership re-derivation, Storage object
// verification, transactional canonical transition and post-commit cleanup —
// lives in functions/src/business/businessMedia.js, which never sees the
// request object and takes db/storage/uuid/clock by injection so it is fully
// unit-testable. `businessMedia` is on firestore.rules' server-owned deny
// list, so this Admin SDK path is the only writer that can ever set it.
exports.finalizeBusinessMedia = onCall(
  { region: "europe-west3" },
  async (request) => {
    try {
      return await finalizeBusinessMediaImpl({
        db: admin.firestore(),
        storage: admin.storage(),
        auth: request.auth,
        data: request.data,
        bucketName: admin.storage().bucket().name,
        uuid: () => crypto.randomUUID(),
        logger,
      });
    } catch (error) {
      if (error instanceof BusinessMediaError) {
        throw new HttpsError(error.code, error.message);
      }
      logger.error("finalizeBusinessMedia_failed", { message: error && error.message });
      throw new HttpsError("internal", "Could not update business media.");
    }
  }
);
